 #define MAX 200010	

class Combination {	
  using _Tp = long long;	
public:	

  _Tp fac[MAX], finv[MAX], inv[MAX];	

  Combination() {	
    init();	
  }	

  void init() {	
    fac[0] = fac[1] = 1;	
    finv[0] = finv[1] = 1;	
    inv[1] = 1;	
  for(int i = 2; i < MAX; i++){	
      fac[i] = fac[i-1] * i % MOD;	
      inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;	
      finv[i] = finv[i-1] * inv[i] % MOD;	
    }	
  }	

   // n!! * k!^(-1) * ((n - k)!)^(-1)	
  _Tp comb(_Tp n, _Tp k) {	
    if (n < k) return 0;	
    if (n < 0 || k < 0) return 0;	
    return fac[n] * (finv[k]* finv[n - k] % MOD) % MOD;	
  }	
};	

