pair<ll, ll> extgcd(ll n, ll m) {
  if (m == 0) return {1, 0};
  auto p = extgcd(m, n % m);
  return {p.second, p.first - n / m * p.second};
}

ll inverse_mod(ll n, ll m) {
  auto p = extgcd(n, m);
  ll x = p.first;
  ll y = p.second;
  assert(n * x + m * y == 1);
  if (x < 0) x += m;
  return x;
}
inline ll factorial(const ll n) {
  return fact[n];
}
ll choose_mod(ll n, ll k) {
  ll a1 = fact[n];

  ll a20 = (fact[k] * fact[n - k]) % K;

  ll ra2 = inverse_mod(a20, K);
  return (a1 * ra2) % K;
}
int ct(int h, int w) {
  if (h == 0 || w == 0) return 0;
  return choose_mod(h + w - 2, min(h, w) - 1);
}
