    scanf("%d%d%d%d",&h,&w,&a,&b);
    for(int i=b+1;i<=w;i++)
    {
        ans=(ans+C(h-a-2+i,i-1)*C(a-1+w-i,w-i)%mod)%mod;
    }
    cout<<ans<<endl;
    return 0;
}

