#include<bits/stdc++.h>
using namespace std;
const long long MOD = 1e9 + 7;

const int W = 200010;
const int M = 1000000007;

long long inv[W];
long long fact[W];
long long factinv[W];

void init() {
  inv[1] = 1;
  for (int i=2; i<W; i++) {
    inv[i] = ((M - inv[M%i]) * (M/i))%M;
  }
  fact[0] = factinv[0] = 1;
  for (int i=1; i<W; i++) {
    fact[i] = (i * fact[i-1])%M;
    factinv[i] = (inv[i] * factinv[i-1])%M;
  }
}

long long nCr(int n, int k)
{
  if (n >=0 && k >= 0 && n-k >= 0) {
    return ((fact[n] * factinv[k])%M * factinv[n-k])%M;
  }
  return 0;
}


int main()
{
  init();

  int H, W, A, B;
  cin >> H >> W >> A >> B;
  --H, --W;
  long long val = nCr(H + W, H);
  for(int i = 0; i < B; i++) {
    long long mos = nCr((H - A) + i, (H - A));
    long long kas = nCr(A - 1 + (W - i), A - 1);
    val += MOD * MOD - mos * kas;
    val %= MOD;
  }
  cout << val << endl;
}

