template<int MOD = 1000000007>class modint {
public:
	modint() {
		this->number = 0;
	}
	modint(int src) {
		this->number = src;
	}
	modint<MOD> operator + (const modint<MOD> obj) {
		modint re((this->number + obj.number) % MOD);
		return re;
	}
	modint<MOD> operator + (const int n) {
		modint re((this->number + opposit(n)) % MOD);
		return re;
	}
	modint<MOD>& operator += (const modint<MOD>& obj) {
		this->number = (this->number + obj.number) % MOD;
		return *this;
	}
	modint<MOD>& operator += (const int n) {
		this->number = (this->number + opposit(n)) % MOD;
		return *this;
	}
	modint<MOD> operator - (const modint<MOD> obj) {
		modint re((this->number - obj.number + MOD) % MOD);
		return re;
	}
	modint<MOD> operator - (const int n) {
		modint re((this->number - opposit(n) + MOD) % MOD);
		return re;
	}
	modint<MOD>& operator -= (const modint<MOD>& obj) {
		this->number = (this->number - obj.number + MOD) % MOD;
		return *this;
	}
	modint<MOD>& operator -= (const int n) {
		this->number = (this->number - opposit(n) + MOD) % MOD;
		return *this;
	}
	modint<MOD> operator * (const modint<MOD> obj) {
		modint re((this->number * obj.number) % MOD);
		return re;
	}
	modint<MOD> operator * (const int n) {
		modint re((this->number * opposit(n)) % MOD);
		return re;
	}
	modint<MOD>& operator *= (const modint<MOD>& obj) {
		this->number = (this->number * obj.number) % MOD;
		return *this;
	}
	modint<MOD>& operator *= (const int n) {
		this->number = (this->number * opposit(n)) % MOD;
		return *this;
	}
	modint<MOD> operator / (const modint<MOD> obj) {
		modint re((this->number * inverse(obj.number)) % MOD);
		return re;
	}
	modint<MOD> operator / (const int n) {
		modint re((this->number * inverse(n)) % MOD);
		return re;
	}
	modint<MOD>& operator /= (const modint<MOD>& obj) {
		this->number = (this->number * inverse(obj.number)) % MOD;
		return *this;
	}
	modint<MOD>& operator /= (const int n) {
		this->number = (this->number * inverse(n)) % MOD;
		return *this;
	}
	modint operator = (const int n) {
		this->number = opposit(n) % MOD;
		return *this;
	}
	int get() {
		return number;
	}

private:
	int number;

	int opposit(int n) {
		if (n < 0)n = MOD - ((-n) % MOD);
		return n % MOD;
	}
	int inverse(int n) {
		n = opposit(n);
		int result = 1;
		for (int i = MOD - 2; i; i /= 2) {
			if (i % 2)result = (result * n) % MOD;
			n = (n * n) % MOD;
		}
		return result;
	}
};

signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int H, W, A, B;
	cin >> H >> W >> A >> B;

	vector<modint<>>facto(H + W + 1);
	facto[0] = 1;
	REP(i, 1, facto.size())facto[i] = facto[i - 1] * i;

	int edgeh = H - A - 1;
	int edgew = B;
	modint<> result(0);
	while (0 <= edgeh && edgew < W) {
		//初期位置からedgeまでのパターン
		auto ans1 = facto[edgeh + edgew] / (facto[edgeh] * facto[edgew]);

		//edgeからゴールまでのパターン
		int eh2 = H - edgeh - 1;
		int ew2 = W - edgew - 1;
		auto ans2 = facto[eh2 + ew2] / (facto[eh2] * facto[ew2]);

		result += (ans1 * ans2);

		edgeh--;
		edgew++;
	}

	cout << result.get() << endl;
}

