const int MAXN = 1e6 + 10;
const int Mod = 1e9 + 7;
int N, M, A, B;
int fac[MAXN], ifc[MAXN];
int ans;

inline int fastpow_mod(int a, int b, int m = Mod) {
	int x = 1;
	while(b) {
		if(b & 1) x = 1ll * x * a % m;
		a = 1ll * a * a % m; b >>= 1;
	}
	return x;
}

inline int C(int n, int k) {
	if(n < k || n < 0 || k < 0) return 0;
	return 1ll * fac[n] * ifc[k] % Mod * ifc[n - k] % Mod;
}

inline void init(int n) {
	register int i;
	for(fac[0] = i = 1; i <= n; ++i) fac[i] = 1ll * fac[i - 1] * i % Mod;
	for(ifc[n] = fastpow_mod(fac[n], Mod - 2), i = n; i; --i) ifc[i - 1] = 1ll * ifc[i] * i % Mod;
}

int main() {
	register int i;
	init(1000000);
	scanf("%d%d%d%d", &N, &M, &A, &B);
	for(i = 1; i <= N - A; ++i)
		(ans += 1ll * C(i + B - 2, B - 1) * C(N - i + M - B - 1, N - i) % Mod) %= Mod;
	printf("%d\n", ans);
	return 0;
}

