    fact[i] = (fact[i-1] * i)%mod;
  }
}

ll factorial(int n,int M){
  if(n<=1) return 1;

  return fact[n];
 }

ll power(int k,int n,int M){
  if(n==0) return 1;
  if(n==1) return (ll)k;

  ll ret = power(k,n/2,M);

  ret=(ret*ret)%M;

  if(n%2==1)
    ret=(ret*k)%M;

  return ret;
}


//nCm nPm nHm (mod M)

/*Combination*/
int C(int n,int m,int M){
  if(n<m) return 0;
  if(m==0 || n==m) return 1;

  ll chi = factorial(n,M);
  ll mot = (factorial(m,M) * factorial(n-m,M))%M;

  mot = power((int)mot,M-2,M);

  ll ret = (chi*mot)%M;

  return (int)ret;
}
/*Permutation*/
int P(int n,int m,int M){
  if(n<m) return 0;
  if(m==0) return 1;

  ll chi = factorial(n,M);
  ll mot = factorial(n-m,M);


  mot = power((int)mot, M-2,M);

  ll ret = (chi*mot)%M;

  return (int)ret;
}

/*Combination with Repetitions*/
int H(int n,int m,int M){
  if(n==0 && m==0) return 1;
  return C(n+m-1,m,M);
}


