ll fast_exp(ll a, ll n)
{
    ll res = 1, base = a;

    while (n)
    {
        if (n & 1)
        {
            res *= base;
            res %= MOD;
        }

        base *= base;
        base %= MOD;

        n >>= 1;
    }

    return res;
}

ll binom(int n, int m)
{
    ll res = (fact[n] * inv[m]) % MOD;
    res = (res * inv[n - m]) % MOD;

    return res;
}

void precomp()
{
    fact[0] = inv[0] = 1;

    for (int n = 1; n < MAX; ++n)
        fact[n] = (n * fact[n - 1]) % MOD;

    for (int n = 1; n < MAX; ++n)
        inv[n] = fast_exp(fact[n], MOD - 2);
}

ll ways(int h, int w)
{
