/**
 * a^b (mod m)
 *
 * 事前条件:
 *   a >= 0 && b >= 0
 */
s64 pow_modulo(s64 a, s64 b, s64 m)
{
    s64 res = 1;

    for(; b > 0; b >>= 1) {
        if(b & 1) {
            res *= a;
            res %= m;
        }
        a *= a;
        a %= m;
    }

    return res;
}

/**
 * mod p での a の逆元
 */
s64 inv_modulo(s64 a, s64 p)
{
    return pow_modulo(a, p-2, p);
}

/**
 * mod p 上での演算をクラス化してみるテスト
 * p は素数とする
 */
template<s64 P>
class ModPT {
public:
    ModPT() : v_(0) {}
    ModPT(s64 v) : v_(v%P) {}

    ModPT& operator+=(const ModPT& rhs)
    {
        v_ += rhs.v_;
        v_ %= P;
        return *this;
    }
    ModPT& operator-=(const ModPT& rhs)
    {
        v_  = (v_+P) - rhs.v_;
        v_ %= P;
        return *this;
    }
    ModPT& operator*=(const ModPT& rhs)
    {
        v_ *= rhs.v_;
        v_ %= P;
        return *this;
    }

    ModPT inv() const
    {
        return ModPT(inv_modulo(v_, P));
    }

    ModPT pow(s64 x) const
    {
        return ModPT(pow_modulo(v_, x, P));
    }

    friend ostream& operator<<(ostream& out, const ModPT<P>& a)
    {
        return out << a.v_;
    }
private:
    s64 v_;
};

template<s64 P>
const ModPT<P> operator+(const ModPT<P>& lhs, const ModPT<P>& rhs) { return ModPT<P>(lhs) += rhs; }
template<s64 P>
const ModPT<P> operator+(const ModPT<P>& lhs, s64 rhs) { return ModPT<P>(lhs) += rhs; }
template<s64 P>
const ModPT<P> operator+(s64 lhs, const ModPT<P>& rhs) { return ModPT<P>(rhs) += lhs; }
template<s64 P>
const ModPT<P> operator-(const ModPT<P>& lhs, const ModPT<P>& rhs) { return ModPT<P>(lhs) -= rhs; }
template<s64 P>
const ModPT<P> operator-(const ModPT<P>& lhs, s64 rhs) { return ModPT<P>(lhs) -= rhs; }
template<s64 P>
const ModPT<P> operator-(s64 lhs, const ModPT<P>& rhs) { return ModPT<P>(rhs) -= lhs; }
template<s64 P>
const ModPT<P> operator*(const ModPT<P>& lhs, const ModPT<P>& rhs) { return ModPT<P>(lhs) *= rhs; }
template<s64 P>
const ModPT<P> operator*(const ModPT<P>& lhs, s64 rhs) { return ModPT<P>(lhs) *= rhs; }
template<s64 P>
const ModPT<P> operator*(s64 lhs, const ModPT<P>& rhs) { return ModPT<P>(rhs) *= lhs; }

using ModP = ModPT<MOD>;

s64 H;
s64 W;

s64 A;
s64 B;

ModP fac[200001];
ModP ifac[200001];

void make_fac()
{
    int n = SIZE(fac);
    fac[0]  = 1;
    ifac[0] = 1;
    FOR(i, 1, n) {
        fac[i]  = i * fac[i-1];
        ifac[i] = fac[i].inv();
    }
}

void solve()
{
    make_fac();

    ModP all = fac[H-1+W-1] * ifac[H-1] * ifac[W-1];

    ModP cmpl = 0;
    REP(i, B) {
        ModP a = 1;
        a *= fac[H-A-1+i] * ifac[i] * ifac[H-A-1];
        a *= fac[A-1+W-i-1] * ifac[W-i-1] * ifac[A-1];
        cmpl += a;
    }

#ifdef DEBUG
    DBG(all);
    DBG(cmpl);
#endif

    ModP ans = all - cmpl;

    PRINTLN(ans);
}

signed main(signed /*argc*/, char** /*argv*/)
{
    RD(H);
    RD(W);

    RD(A);
    RD(B);

#ifdef DEBUG

#endif

    solve();

    EXIT();
}

#include <cstdio>
typedef long long int64;
static const int MAXN = 200005;
static const int MODULUS = 1e9 + 7;
#define _  %  MODULUS
#define __ %= MODULUS

int h, w, a, b;
int64 fact[MAXN], fact_inv[MAXN];

inline int64 fpow(int64 base, int exp)
{
    int64 ans = 1;
    for (; exp; exp >>= 1, (base *= base)__) if (exp & 1) (ans *= base)__;
    return ans;
}

inline void preprocess()
{
    fact[0] = 1;
    for (int i = 1; i < MAXN; ++i) fact[i] = fact[i - 1] * i _;
    fact_inv[MAXN - 1] = fpow(fact[MAXN - 1], MODULUS - 2);
    for (int i = MAXN - 2; i >= 0; --i) fact_inv[i] = fact_inv[i + 1] * (i + 1)_;
}

inline int64 binom(int n, int m)
{
