	ll k = 1;
	rep(i, H + W + 1) {
		if (i == 0)fact[i] = 1;
		else {
			k *= i;
			fact[i] = k%mod;
			k %= mod;
		}
	}
	ll ans = 0;
	reps(i, 1,H - A+1) {
		ans += mod_comb(B - 1 + i - 1, B - 1, mod)*mod_comb(W - B - 1 + H - i, W - B - 1, mod);
		ans %= mod;
	}

	cout << ans << endl;
	return 0;
}

