ll powmod(ll a, ll b) {
    if (b == 0) return 1;
    if (b % 2 == 0) {
        ll x = powmod(a, b / 2);
        return (x * x) % mod;
    }
    return (a * powmod(a, b - 1)) % mod;
}

void calcFactorials() {
    fact[0] = 1;
    forn1(i, maxn) fact[i] = (fact[i - 1] * (ll) i) % mod;
    forn(i, maxn) invfact[i] = powmod(fact[i], mod - 2);
}

ll cnk(int n, int k) {
    return ((fact[n] * invfact[k]) % mod) * invfact[n - k] % mod;
}

