ll power_ll_p(ll a, ll b, ll p)	//F_pでのべき
{
  if (b > p)
  {
    b %= (p - 1);//位数p-1
  }
  if (b == 0)
  {
    return 1;
  }
  if (b % 2 == 0)
  {
    ll t = power_ll_p(a, b / 2, p);
    return t * t % p;
  }
  else
  {
    return a * power_ll_p(a, b - 1, p) % p;
  }
}

ll combination_p(ll n, ll r, ll p)	//コンビネーション
{
  if (r > n - r)
  {
    r = n - r;
  }
  ll ans = 1;
  for (ll i = 0; i < r; i++)
  {
    ans *= n - i;
    ans %= p;
  }
  ll subans = 1;
  for (ll i = 0; i < r; i++)
  {
    subans *= i + 1;
    subans %= p;
  }
  ans *= power_ll_p(subans, p - 2, p);		//逆元は^(p-2)
  ans %= p;
  return ans;
}

ll extgcd(ll a, ll b, ll&x, ll&y)
{
  if (b == 0)
  {
    x = 1;
    y = 0;
    return a;
  }
  else
  {
    ll q = a / b;
    ll g = extgcd(b, a - q * b, x, y);
    ll z = x - q * y;
    x = y;
    y = z;
    return g;
  }
}

//modp逆元
ll inversemod(ll a, ll p)
{
  ll x, y;
  extgcd(a, p, x, y);
  x %= p;
  if (x < 0)
  {
    x += p;
  }
  return x;
}

const ll mod = 1e9 + 7;

int main()
{
  ll h, w, a, b;
  cin >> h >> w >> a >> b;
  ll ans = 0;
  ll check = combination_p(a + w - b - 1, a, mod) * combination_p(b + h - a - 1, b, mod);
  check %= mod;
  ll i = a;
  ll j = b;
  while (i <= h && j <= w)
  {
    ans += check;
    ans %= mod;
    i++;
    j++;
    check *= a + w - b - i;
    check %= mod;
    check *= b + h - a - j;
    check %= mod;
    check *= inversemod(i, mod);
    check %= mod;
    check *= inversemod(j, mod);
    check %= mod;
  }
  cout << (ans + mod) % mod << "\n";
}

