const ll mod = 1e9 + 7;
const int nmax = 200500;

void add(ll& a, ll b)
{
    a += b;
    if (a >= mod) {
        a -= mod;
    }
}

void mul(ll& a, ll b)
{
    a *= b;
    if (a >= mod) {
        a %= mod;
    }
}

ll binpow(ll a, ll n)
{
    ll ans = 1;
    while (n) {
        if (n & 1) {
            mul(ans, a);
        }
        n >>= 1;
        if (n) {
            mul(a, a);
        }
    }
    return ans;
}

vector<ll> fact(nmax), rfact(nmax);

ll choose(int n, int k)
{
    ll ans = fact[n];
    mul(ans, rfact[k]);
    mul(ans, rfact[n - k]);
    return ans;
}

int main()
{

    //ifstream cin("input.txt");
    //freopen("input.txt", "r", stdin);

    //ios_base::sync_with_stdio(false);
    //cin.tie(0);

    fact[0] = rfact[0] = 1;
    for (int i = 1; i < nmax; ++i) {
        fact[i] = fact[i - 1];
        mul(fact[i], i);
        rfact[i] = binpow(fact[i], mod - 2);
    }

    int n, m, a, b;
    cin >> n >> m >> a >> b;
    ll ans = 0;
    a = n - a;

    for (int i = 0; i < a; ++i) {
        ll val = choose(b + i - 1, b - 1);
        mul(val, choose(n + m - b - i - 2, n - i - 1));
        add(ans, val);
    }

    cout << ans << "\n";

}

