typedef long long ll;
ll M=1000000007;
ll nCk(ll n,ll k){
  if(n<k)swap(n,k);
  if(k==0)return 1;
  if(2*k>n)k=n-k;
  ll a=1;
  for(ll i=0;i<k;i++){
    a*=(n-k+i+1)%M;
    a/=i+1;a%=M;
  }
  return a;
}
int main(){
  ll h,w,a,b;cin>>h>>w>>a>>b;
  ll sum=0;
  for(ll i=0;i<h-a;i++){
    sum+=nCk(b-1+i,b-1)*nCk(h+w-b-2-i,w-b-1);
    sum%=M;
  }
  cout<<sum%M<<endl;
}

#include<cstdio>
#define R 100001
#define MOD 1000000007
int h, w, a, b;
long long way[R];
long long mul(long long x, long long y, long long p) {
	long long res = 1;
	while (y > 0) {
		if (y % 2 != 0) {
			res *= x;
			res %= p;
		}
		x *= x;
		x %= p;
		y /= 2;
	}
	return res;
}
int main() {
	scanf("%d%d%d%d", &h, &w, &a, &b);
	int i;
	long long comba=1,combb=1;
	long long ans = 0;
	for (i = 0; i < h - a; i++) {
		if (i > 0) {
			comba *= (b + i-1);
			comba %= MOD;
			combb *= i;
			combb %= MOD;
		}
		long long combc = mul(combb, MOD - 2, MOD);
		way[i] = (comba*combc) % MOD;
	}
	comba = 1; combb = 1;
	for (i = 1; i < a; i++) {
		comba *= (w - b - 1+i);
		combb *= i;
		comba %= MOD;
		combb %= MOD;
	}
	for (i = a; i < h; i++) {
		comba *= (w - b - 1 + i);
		combb *= i;
		comba %= MOD;
		combb %= MOD;
		long long combc = mul(combb, MOD - 2, MOD);
		long long comb = (comba*combc) % MOD;
		long long next = (comb * way[h-1 - i])%MOD;
		ans = (ans + next) % MOD;
	}
	printf("%lld", ans);
	return 0;
}

