    LL ans = nCr(n + m - 2, m - 1);
    for(LL i = n-a+1; i <= n; i++) {
        LL x = nCr(i-1 + b-1, b-1), y = nCr(n-i + m-b-1, n-i);
        LL z = (x * y) % mod;
        ans -= z;
        if(ans < 0) ans += mod;
    }
    cout << ans;
}

