ll n = 200001;

def extgcd(ll a, ll b, ll &x, ll &y) {
    if (b == 0) {
        x = 1, y = 0;
        return a;
    }
    ll d = extgcd(b, a % b, y, x);
    y -= a / b * x;
    return d;
}

def mod_inv(ll a) {
    ll x, y;
    ll d = extgcd(a, MOD, x, y);
    return (d == 1) * ((x + MOD) % MOD);
}

int dataf[200001], datai[200001];
ll mod_fact(ll a) {
    if (a <= 0) return 1;
    if (dataf[a]) return dataf[a];
    return dataf[a] = mod_fact(a - 1) * a % MOD;
}

ll mod_inv_fact(ll a) {
    if (a >= n) return mod_inv(mod_fact(n));
    if (datai[a]) return datai[a];
    return datai[a] = mod_inv_fact(a + 1) * (a + 1) % MOD;
}

ll mod_comb_fast(ll n, ll r) {
    if (r < 0 || n < r) return 0LL;
    if (r == 0 || r == n) return 1LL;
    return mod_fact(n) * mod_inv_fact(n - r) % MOD * mod_inv_fact(r) % MOD;
}

signed main() {
    ll H, W, A, B;
    cin >> H >> W >> A >> B;
    ll res = 0;
    rep(i, H - A) {
        ll p = mod_comb_fast((B - 1) + (i), i);
        ll q = mod_comb_fast((W - B - 1) + (H - i - 1), H - i - 1);
        res += p * q;
        res %= MOD;
    }
    cout << res << endl;
}

