    for(ll i = 2;i <= h+w-2;i++){
        factorial[i] = factorial[i-1] * i % MOD;
    }
    for(ll i = 0;i <= h+w-2;i++){
        inverse[i] = calc(factorial[i],MOD-2,MOD);
    }

    ll n = h-a-1;
    ll down = a-1;
    ll ans = 0;

    for(ll i = b;i < w;i++){

        ll right = w-i-1;
        //cout << right << endl;
        ans = (ans + (calc_nCr(n+i,i) * calc_nCr(down+right,right))%MOD)%MOD;
