lli powerr(int a, int b) {
	if(b == 0) {
		return 1;
	} else if(b == 1) {
		return a;
	} else {
		lli base = powerr(a, b/2);
		lli ans = base*base % MOD;
		if(b%2) {
			ans *= a;
			ans %= MOD;
		}
		return ans;
	}
}

void initFac() {
	fac[0] = fac[1] = 1;
	for(int i = 2; i < 2*LIM; i++) {
		fac[i] = i*fac[i-1];
		fac[i] %= MOD;
	}
}

