inline int add(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    if (a < 0) a += MOD;
    return a;
}

inline int mul(int a, int b) {
    return a * (long long) b % MOD;
}

inline int expow(int a, int b) {
    int ans = 1;
    while (b) {
        if (b & 1) ans = mul(ans, a);
        a = mul(a, a);
        b >>= 1;
    }
    return ans;
}

inline int comb(int n, int k) {
    int p = mul(f[k], f[n - k]);
    int inv = expow(p, MOD - 2);
    return mul(f[n], inv);
}

inline void BuildFact() {
    f[0] = 1;
    for (int i = 1; i < N; i++)
        f[i] = mul(f[i - 1], i);
}

inline int cnt(int r1, int c1, int r2, int c2) {
    int n = r2 - r1;
    int m = c2 - c1;
    int sm = n + m;
    return comb(sm, n);
}

