		long long int mul = A;
		for( ; P > 0; P >>= 1, mul = (mul*mul) % M ) {
			if( (P & 1) == 1 ) ans = (ans*mul) % M;
		}
		return ans;
	}

	//nCk mod m
	inline long long int cb( long long int N, long long int K, long long int M = LLONG_MAX ) {
		if( N < combinationThreshold ) {// 事前計算O(N)、答えるのはO(1)
			if( inv.size() == 0 ) {
				inv = vector<long long int>( combinationThreshold );
				inv[1] = 1;
				for( long long int i = 2; i < combinationThreshold; i++ ) {
					inv[i] = M - (M / i)*inv[M%i] % M;
				}
				fact = vector<long long int>( combinationThreshold );
				fact[0] = 1;
				revFact = vector<long long int>
					( combinationThreshold );
				revFact[0] = 1;
				for( long long int i = 1; i < combinationThreshold; i++ ) {
					fact[i] = (fact[i - 1] * i) % M;
					revFact[i] = (revFact[i - 1] * inv[i]) % M;
				}
			}
			return (((fact[N] * revFact[K]) % M)*revFact[N - K]) % M;
		} else {
			return cbOnce( N, K, M );
		}
	}

	//一回だけなら最速 O(K + log(M))
	inline long long int cbOnce( long long int N, long long int K, long long int M = LLONG_MAX ) {
		if( K > N / 2 ) return cb( N, N - K, M );
		long long int ans = 1;
		long long int div = 1;
		for( long long int i = 0; i < K; i++ ) {
			ans *= N - i;
			ans %= M;
			div *= i + 1;
			div %= M;
		}
		ans *= powmod( div, M - 2, M );
		return ans%M;
	}

private:
	vector<vector<long long int>>C;//3000以下の答え
	vector<long long int>fact;//階乗
	vector<long long int>revFact;//階乗の逆元
	vector<long long int>inv;//mod pでの逆元

	long long int combinationThreshold;//Nの最大値がわかれば入れる。
};

int main() {
	long long int H, W, A, B;
	cin >> H >> W >> A >> B;
	long long int ans = 0;
	if( min( H - A, W - B ) > min( A, B ) ) {
		combination cb( max( H - A + B - 1, A + W - B - 1 ) +2);
		for( long long int i = 0, lim = min( A, B ); i < lim; i++ ) {
			ans += cb.cb( H - A + B - 1, -i + B - 1, 1e9 + 7 )*cb.cb( A + W - B - 1, -i + A - 1, 1e9 + 7 );
			ans %= (long long int)1e9 + 7;
		}
		ans = (cb.cbOnce( H + W - 2, H - 1, 1e9 + 7 ) - ans + (long long int)1e9 + 7) % (long long int)(1e9 + 7);
	} else {
		combination cb( max( H - A + B - 1, A + W - B - 1 ) + 2 );
		for( long long int i = 0, lim = min( H - A, W - B ); i < lim; i++ ) {
			ans += cb.cb( H - A + B - 1, i + B, 1e9 + 7 )*cb.cb( A + W - B - 1, i + A, 1e9 + 7 );
			ans %= (long long int)1e9 + 7;
		}
	}
