		int tmp=(ll)C(n-a+i-2,n-a-1)*C(a+m-i-1,a-1)%mod;
		//printf("i=%d,tmp=%d\n",i,tmp);
		upd(ans,tmp);
	}
	printf("%d\n",ans);
	return 0;
}

