long long PowerMod(long long Base, long long Exp, long long Mod)
{
	Base %= Mod;
	long long Ret = 1;
	while (Exp)
	{
		if (Exp & 1)
			(Ret *= Base) %= Mod;
		(Base *= Base) %= Mod;
		Exp >>= 1;
	}
	return Ret;
}
