ll fact[maxn];
ll pw(ll a, ll n){
  if(n == 0) return 1;
  ll b = pw(a, n>>1);
  b = b * b % mod;
  if(n & 1) b = b * a % mod;
  return b;
}

ll binom(int n, int k){
  assert(k >= 0 && k <= n);
  ll denom = fact[k] * fact[n-k] % mod;
  denom = pw(denom, mod-2) * fact[n] % mod;
  return denom;
}

ll perform(int x, int y){
  x--;
  y--;
  return binom(x+y, y);
}

