int pw(int x, int n) {
    int res = 1;
    while (n > 0) {
        if (n % 2 == 1) {
            res = mul(res, x);
            n--;
        }
        x = mul(x, x);
        n /= 2;
    }
    return res;
}

int fact[N];
int rfact[N];

int C(int n, int k) {
    return mul(fact[n], mul(rfact[n - k], rfact[k]));
}

