    init_fact(10000000,mod);
    rep(y,0,h-a) ans=(ans+mod_comb(y+b-1,y,mod)*mod_comb((h-y-1)+(w-b-1),h-y-1,mod)%mod)%mod;
    cout << ans << endl;
}

