const int MOD = 1000000007;

int H, W, A, B;

const int MAXCOMB = 200000 + 10; // NEED TO CHECK
long long Fac[MAXCOMB], InvFac[MAXCOMB];
long long CombMod(long long A, long long B)
{
	long long Ans = Fac[A];
	(Ans *= InvFac[B]) %= MOD;
	(Ans *= InvFac[A - B]) %= MOD;
	return Ans;
}
long long PowerMod(long long Base, long long Exp, long long Mod)
{
	Base %= Mod;
	long long Ret = 1;
	while (Exp)
	{
		if (Exp & 1)
			(Ret *= Base) %= Mod;
		(Base *= Base) %= Mod;
		Exp >>= 1;
	}
	return Ret;
}
void GenFactorial()
{
	Fac[0] = 1;
	for (int i = 1; i < MAXCOMB; i ++)
		Fac[i] = ((long long) Fac[i - 1] * (long long) i) % MOD;
	InvFac[MAXCOMB - 1] = PowerMod(Fac[MAXCOMB - 1], MOD - 2, MOD);
	for (int i = MAXCOMB - 1; i >= 1; i --)
		InvFac[i - 1] = ((long long) InvFac[i] * (long long) i) % MOD;
}

void Work()
{
	GenFactorial();
	scanf("%d%d%d%d", &H, &W, &A, &B);
	long long Ans = 0;
	for (int i = B; i < W; i ++)
	{
		Ans += CombMod(H - A - 1 + i, H - A - 1) * CombMod((H + W - 2) - (H - A - 1 + i) - 1, A - 1) % MOD;
		Ans %= MOD;
	}
	printf("%d\n", (int) Ans);
}

int main()
{
	Work();
	return 0;
}

