struct modint {
  int v;
  modint(int a = 0)
    : v(((a % MOD) + MOD) % MOD) {
  }
  modint operator+(const modint& b) const {
    return (v + b.v) % MOD;
  }
  modint operator-(const modint& b) const {
    return (v - b.v + MOD) % MOD;
  }
  modint operator*(const modint& b) const {
    return (v * b.v) % MOD;
  }
  modint operator/(const modint& b) const {
    return (v * powm(b.v, MOD - 2, MOD)) % MOD;
  }
};
bool operator==(const modint& a, const modint& b) {
  return a.v == b.v;
}
modint& operator+=(modint& a, const modint& b) {
  return a = a + b;
}
modint& operator-=(modint& a, const modint& b) {
  return a = a - b;
}
modint& operator*=(modint& a, const modint& b) {
  return a = a * b;
}
modint& operator/=(modint& a, const modint& b) {
  return a = a / b;
}

ostream& operator<<(ostream& out, const modint& a) {
  return out << a.v;
}
istream& operator>>(istream& in, modint& a) {
  int v;
  in >> v;
  a = modint(v);
  return in;
}

void solve() {
  int h, w, a, b;
  cin >> h >> w >> a >> b;
  vector<modint> factorial(h + w);
  factorial[0] = 1;
  loop(i, 1, factorial.size()) factorial[i] = modint(i) * factorial[i - 1];
  auto ncr = [&](const int& n, const int& r) {
    return factorial[n] / (factorial[n - r] * factorial[r]);
  };
  auto ways = [&](const int& c, const int& r) {
    return ncr(c + r, c);
  };
  modint s = 0;
  loop(i, b, w) s += ways(h - a - 1, i) * ways(a - 1, w - 1 - i);
  cout << s << endl;
}

