template<class T>
static T inv(T a)
{
    T b=MOD;
    T u=0, v=1;
    while(a)
    {
        const auto t=b/a;
        std::swap(b-=t*a,a);
        std::swap(u-=t*v,v);
    }
    return (u+MOD)%MOD;
}

