const ll MOD7 = 1000000007;

struct FactorialTable {
  vector<ll> fact;
  vector<ll> inv;
  ll m;

  explicit FactorialTable(ll n, ll m) {
    this->m = m;
    fact = vector<ll>(n + 1, 0);
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
      fact[i] = fact[i - 1] * i % m;
    }
    cout << endl;
    inv = vector<ll>(n + 1, 0);
    inv[n] = mod_pow(fact[n], m - 2, m);
    for (int i = n - 1; i >= 0; i--) {
      inv[i] = inv[i + 1] * (i + 1) % m;
    }
  }
  ll mod_pow(ll x, ll n, ll m) {
    ll ans = 1;
    while (n > 0) {
      if ((n & 1) == 1) ans = ans * x % m;
      x = x * x % m;
      n >>= 1;
    }
    return ans;
  }
  ll factorial(int n) {
    return fact[n];
  }
  ll comb(int n, int k) {
    return fact[n] * inv[k] % m * inv[n - k] % m;
  }
};

