  ll result = 0;
  for (int i = B + 1; i <= W; i++) {
    result += f.comb(H - A + i - 2, i - 1) *
              f.comb(A + W - i - 1, A - 1) % MOD7;
  }
  cout << result << endl;
  return 0;
}

