VL factdp(200010, 0);

// n! mod MODを計算
ll fact(ll n) {
  if (factdp[n] > 0) {
    return factdp[n];
  }

  factdp[n] = fact(n - 1) * n % MOD;
  return factdp[n];
}

// 繰り返し二乗法でn^timesを計算
ll powMOD(ll n, ll times) {
  if (times == 1) {
    return n % MOD;
  }

  if (times % 2 > 0) {
    return powMOD(n, times - 1) * n % MOD;
  } else {
    return powMOD(n * n % MOD, times / 2);
  }
}

// factの逆元を計算
ll invfact(ll n) {
  return powMOD(fact(n), MOD - 2);
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  factdp[0] = 1;

  ll H, W, A, B;
  cin >> H >> W >> A >> B;

  fact(50000);

  ll sum = 0;
  for (ll i = 0; i < W - B; i++) {
    // 図を書けば分かる
    ll former = fact(B + H - A - 1 + i) * invfact(B + i) % MOD * invfact(H - A - 1) % MOD;
    ll later = fact(A + W - B - 2 - i) * invfact(W - B - 1 - i) % MOD * invfact(A - 1) % MOD;
    sum += former * later % MOD;
    sum %= MOD;
  }

  cout << sum << endl;
  return 0;
}

