/** 累乗

   O(log n)
 */
template<typename T, T M>
T power(T x, T y)
{
    T ret = 1;
    for (; y != 0; y /= 2) {
        if (y % 2 != 0) {
            ret = (ret * x) % M;
        }
        x = (x * x) % M;
    }
    return ret;
}

// P を法とする逆元
template<typename T, T P>
T mod_inv(T x) {
    return power<T, P>(x, P-2);
}

/** Pを法とする  static なメモ付きべき乗
 */
template<typename T, T P>
std::pair<T, T> memo_flactional(T val)
{
    static std::vector<T> memo{1};
    static std::vector<T> inv_memo{1};

    if (memo.size() <= val) {
        memo.reserve(val+1);
        inv_memo.reserve(val+1);
        for (T i = memo.size(); i <= val; ++i) {
            memo.push_back((memo[i-1] * i) % P);
            inv_memo.push_back((inv_memo[i-1] * mod_inv<T, P>(i)) % P);
        }
    }

    return std::make_pair(memo[val], inv_memo[val]);
}

// http://hos.ac/slides/20130319_enumeration.pdf

/** P を法とする組み合わせ
 */
template<typename T, T P = 1000000007ULL>
T choose(T n, T r)
{
    T ret = memo_flactional<T, P>(n).first;
    ret *= memo_flactional<T, P>(r).second;
    ret %= P;
    ret *= memo_flactional<T, P>(n - r).second;
    ret %= P;

    return ret;
}


int main()
{
    uint64_t H, W, A, B;
    std::cin >> H >> W >> A >> B;

    constexpr uint64_t P = 1000000007ULL;

    // 最大パターン計算してメモっておく
    memo_flactional<uint64_t, P>(H+W);

    uint64_t path = 0;
    for (uint64_t i = B; i <= W - 1; ++i) {
        path +=
            choose<uint64_t, P>((H - A - 1) + i,                    i) *
            choose<uint64_t, P>((A - 1)     + (W - 1 - i), (W - 1 - i));
        path %= P;
    }

    std::cout << path << std::endl;

    return 0;
}

