template <class Val>
vector<Val> factorials(int n){
    vector<Val> res(n + 1);
    res[0] = res[1] = 1;
    for(int i = 2; i <= n; ++i)
        res[i] = res[i - 1] * i;
    return res;
}

vector<mint> F;
mint calc(int x, int y) {
    return F[x + y] / (F[x] * F[y]);
}

