	FOR(i,0,W-B){
		b[i]=nck[i];
	}
	//
	ll ans=0;
	int aa=H-A-1,bb=W-B-1;
	while(aa>=0&&bb>=0){
		(ans+=a[aa]*b[bb])%=mod;
		aa--;bb--;
	}
