public:
    vector<long long> fact, rev;
    Combination(int n = 200005) : fact(n), rev(n) {
        fact[0] = fact[1] = 1;
        for(int i = 2; i < n; i ++){
            (fact[i] = fact[i - 1] * i) %= M;
        }
        rev[n - 1] = power(fact[n - 1], M - 2) % M;
        for (int i = n - 1; i > 0; i--) {
            rev[i - 1] = rev[i] * i % M;
        }
    }
    long long power(long long x, long long n){
        long long res = 1;
        if(n > 0){
            res = power(x, n / 2);
            if(n % 2 == 0) res = (res * res) % M;
            else res = (((res * res) % M) * x ) % M;
        }
        return res;
