int gyakugen(int n){
  int ret = 1, nownum = n, m = MOD - 2;
  while(m > 0){
    if(m & 1){
      ret *= nownum;
      ret %= MOD;
    }
    nownum *= nownum;
    nownum %= MOD;
    m >>= 1;
  }
  return ret;
}

int soujou(int n){
  if(n == 1 || n == 0){
    return 1;
  }
  if(dp[n] != -1){
    return dp[n];
  }
  return dp[n] = n * soujou(n - 1) % MOD;
}

int gyakusoujou(int n){
  if(n == 1 || n == 0){
    return 1;
  }
  if(gyakudp[n] != -1){
    return gyakudp[n];
  }
  return gyakudp[n] = gyakugen(n) * gyakusoujou(n - 1) % MOD;
}

