const ll mod = 1e9 + 7;
ll emod(ll x, ll p = mod) {
  return (x % p + p) % p;
}
int comb(int n, int r, int mod = 0) {
  assert(n >= 0 and r >= 0);
  if (r > n) return 0;
  r = min(r, n - r);
  int res = 1;
  if (mod) for (int i = 0; i < r; i++) res = res * (n - i) / (i + 1) % mod;
  else for (int i = 0; i < r; i++) res = res * (n - i) / (i + 1);
  return res;
}
