  if (a < b) {
    swap(a, b);
    swap(h, w);
  }
  for (int i = 0; i < b; i++) res = emod(res - comb(h - a + b - 1, i, mod) * comb(w + a - b - 1, w - 1 - i, mod) % mod);
  cout << res << "\n";
  return 0;
}

