int mypow(int p, int q) {
	int ret = 1;
	while (q > 0) {
		if (q%2) ret = (1ll*ret*p) % MOD;
		p = (1ll*p*p) % MOD;
		q /= 2;
	}
	return ret;
}
int inv(int p) {
	return mypow(p,MOD-2);
}
int fact(int x) {
	int ret = 1;
	for (int i=1;i<=x;i++) ret = (1ll * ret * i) % MOD;
	return ret; 
}
