class CombinationModM {
 public:
  ll M;

  vector<ll> factorial_n = vector<ll>(300001, 0);
  vector<ll> factorial_km2 = vector<ll>(300001, 0);

  explicit CombinationModM(const ll &m) {
    this->M = m;
    pre_calc();
  }

  ll calc(const ll &n, const ll &r) {
    if (n == 0 and r == 0) return 1;
    if (n < r and n < 0) return -1;
    ll tmp = factorial_km2[n - r] * factorial_km2[r] % M;
    return tmp * factorial_n[n] % M;
  }

 private:
  ll llpow(ll x, ll n) {
    ll ans = 1;
    while (n != 0) {
      if (n & 1) ans = ans * x % M;
      x = x * x % M;
      n = n >> 1;
    }
    return ans;
  }

  void pre_calc() {
    factorial_n[0] = 1;
    factorial_km2[0] = 1;
    for (ll i = 0; i < 300000; ++i) {
      factorial_n[i + 1] = factorial_n[i] * (i + 1) % M;
      factorial_km2[i + 1] = factorial_km2[i] * llpow(i + 1, M - 2) % M;
    }
  }

};

