  CombinationModM cmb(mod);
  ll cnt = 0;
  REP(i, b, w) {
    cnt += cmb.calc(h - a + i - 1, i) * cmb.calc(w - i + a - 2, a - 1) % mod;
    cnt %= mod;
  }

  ccout << cnt << endl;

}

