ll prime[100000*2+1];
ll getPrime(ll i){
    if(prime[i])return prime[i];
    if(i == 0)return prime[i] = 1;
    return prime[i] = (i * getPrime(i-1)) %MOD;
}

ll nck_mod(ll n, ll k, ll p) {
    ll numerator = (getPrime(n) * modInverse(getPrime(n-k), MOD))%MOD;
    ll denominator = getPrime(k);
    return ( numerator* modInverse(denominator,p) ) % p;
}


