int rf[arr];

int C(int n,int k)
{
    return f[n]*rf[k]%md*rf[n-k]%md;
}

int ways(int n,int m)
{
    return C(n+m-2,n-1);
}

int ways(int x1,int y1,int x2,int y2)
{
    return ways(x2-x1+1,y2-y1+1);
}

