const int INF = 1 << 30;
const int MOD = 1e9 + 7;
const int N = 2e5 + 10;
int F[N];

int64 power_mod(int64 a, int n) {
  int64 ret = 1;
  for (; n; n >>= 1) {
    if (n & 1) ret = ret * a % MOD;
    a = a * a % MOD;
  }
  return ret;
}

int64 inv_mod(int64 a) {
  return power_mod(a, MOD - 2);
}

int64 comb(int n, int m) {
  return F[n] * inv_mod(F[m]) % MOD * inv_mod(F[n - m]) % MOD;
}

int main() {
  F[0] = 1;
  for (int i = 1; i < N; ++i) F[i] = (int64)F[i - 1] * i % MOD;
  int H, W, A, B;
  cin >> H >> W >> A >> B;
  int ret = 0;
  int pre = 0;
  for (int i = B + 1; i <= W; ++i) {
    int cur = comb(H - A + i - 2, i - 1);
    ret += (cur + MOD - pre) * comb(A + W - i, W - i) % MOD;
    ret %= MOD;
    pre = cur;
  }
  cout << ret << endl;
  return 0;
}

