void solve(){
	int H,W,A,B;
	cin >> H >> W >> A >> B;
	LL ans = 0;

	vector< LL > inv(200001);
	makeinv(inv,MOD);
	int r = 1;
	LL res1 = nCk(r+B-2,r-1);
	LL res2 = nCk(H-r+(W-B)-1,H-r);
	LL res = (res1*res2)%MOD;
	ans = res;
	for(r=2;r<=H-A; ++r){
		LL rr = r-1;
		{
			res1 = (res1 * (r+B-2))%MOD;
			res1 = (res1 * inv[r-1])%MOD;
		}
		{
			res2 = (res2 * (H-rr))%MOD;
			res2 = (res2 * inv[H-rr+W-B-1]) % MOD;
		}
		res = (res1*res2)%MOD;
		ans = (ans + res) % MOD;
	}
	cout << ans << endl;
}

