const long long mod = 1000000007; 

long long Pow(long long a, long long b) {
    long long cnt, ret; 
    cnt = a; 
    ret = 1; 
    while (b) {
        if (b & 1) ret = ret * cnt % mod;
        cnt = cnt * cnt % mod; 
        b >>= 1;  
    }
    return ret; 
}

long long inv(long long a) {
    return Pow(a, mod - 2); 
}

int main() {
    ios::sync_with_stdio(false);
