    st.resize(m - b);
    ed.resize(m - b); 
    st[0] = 1;
    for (int i = n - a + b - 1; i >= n - a; --i) st[0] = st[0] * i % mod; 
    for (int i = 1; i <= b; ++i) st[0] = st[0] * inv(i) % mod; 
    for (int i = 1; i < m - b; ++i) {
        st[i] = st[i - 1] * (n - a + b + i - 1) % mod; 
        st[i] = st[i] * inv(b + i) % mod; 
    }
//    for (int i = 0; i < m - b; ++i)
