const ll mod=1e9+7;
ll fac[N],ans=0;
ll C(ll n,ll m)
{
	if(n<m)return 0;
	return fac[n]%mod*inv(fac[m],mod)%mod*inv(fac[n-m],mod)%mod;
}
ll Lucas(ll n,ll m)
{
	if(!m)return 1;
	return C(n%mod,m%mod)*Lucas(n/mod,m/mod);
}
int main()
{
