// nCr
ll nCr(ll n,ll r){
	ll out=1;
	r=min(r,n-r);
	for(ll i=n;i>n-r;i--)out=out*(i%MOD)%MOD;
	ll t=1;
	for(ll i=2;i<=r;i++)t=t*i%MOD;
	return out*powmod(t,MOD-2)%MOD;
}
