	factorial[0] = 1; inverse[0] = 1;
	for (int i=1; i<=H+W; i++) {
		factorial[i] = factorial[i-1] * i % MOD;
		inverse[i] = exponentiation(factorial[i], MOD-2);
	}

	int ans = 0;
	for (int x=B+1; x<=W; x++) {
		ans += combination(x+H-A-2, x-1) * combination(W-x+A-1, A-1) % MOD;
		ans %= MOD;
	}
	cout << ans << endl;
	return 0;
}

