    long long pwval=1,cur=1;
    pw[0]=1;
    pw[1]=num;
    while(pwval*2<=tar)
    {
        pw[cur+1]=pw[cur]*pw[cur];
        pw[cur+1]%=md;
        pwval*=2;
        cur++;
    }
    long long ret = pw[cur];
    long long left = tar-pwval;
    pwval/=2;
    for(int i=cur-1;i>=0;i--,pwval/=2)
    {
        if(pwval<=left)
        {
            left-=pwval;
            ret*=pw[i];
            ret%=md;
        }
    }
    return (int)ret;
}

