const int MOD = ((int)1e9) + 7;

int invmod(int n, int m) {
	int res = 1;
	int k = m - 2;
	while(k > 0) {
		if(k & 1) {
			res *= n;
			res %= m;
		}
		k >>= 1;
		n *= n;
		n %= m;
	}
	return res;
}

int comb(int n, int m) {
	int res = 1;
	for(int i = n; i > 0; --i) {
		res = (res * i) % MOD;
	}
	for(int i = m; i > 0; --i) {
		res = (res * invmod(i, MOD)) % MOD;
	}
	for(int i = n-m; i > 0; --i) {
		res = (res * invmod(i, MOD)) % MOD;
	}
	return res;
}

vector<int> calc(int w, int h) {
	int n = 1;
	vector<int> res(w + 1);

	for(int i = 0; i < w; ++i) {
		int tmp = comb(i + h, i);
		//assert(tmp == n);
		res[i] = n;
		n = (n * (i + h + 1)) % MOD;
		n = (n * invmod(i + 1, MOD)) % MOD;
	}
	res[w] = comb(w + h, w);
	res[w] = n;
	return res;
}

