typedef long long ll;
#define M 1000000007

ll pot(ll a, ll b) {
    if (b == 0) return 1;
    ll u = pot(a,b/2);
    u = u*u;
    u %= M;
    if (b%2 == 1) u *= a;
    u %= M;
    return u;
}

ll inv(ll x) {
    return pot(x,M-2);
}

ll f[202020];

ll ncr(ll a, ll b) {
    if (b > a) return 0;
    ll u = 1;
    u *= f[a];
    u %= M;
    u *= inv(f[b]);
    u %= M;
    u *= inv(f[a-b]);
    u %= M;
    return u;
}

ll matka(ll a, ll b) {
    return ncr(a+b-2,a-1);
}

