int power(int x, int y) {
	if (!y) return 1;
	int ret = power(x, y >> 1);
	ret = 1ll * ret * ret % mod;
	if (y & 1) ret = 1ll * ret * x % mod;
	return ret;
}

void init() {
	A[0] = 1;
	revA[0] = 1;
	for (int i = 1; i < maxn; ++i) {
		A[i] = 1ll * A[i - 1] * i % mod;
	}
	revA[maxn - 1] = power(A[maxn - 1], mod - 2);
	for (int i = maxn - 2; i >= 1; --i) {
		revA[i] = 1ll * revA[i + 1] * (i + 1) % mod;
	}
}

int C(int n, int m) {
	return (1ll * A[n] * revA[m] % mod * 1ll * revA[n - m] % mod);
}

