int pow (int a, int b)
{
    int p = 1;
    for (int i=0; (1<<i) <= b; i++)
    {
        if (b & (1 << i)) p = mul (p, a);
        a = mul (a, a);
    }
    return p;
}

void Prec (int lim)
{
    fac[0] = inv[0] = 1;
    for (int i=1; i<=lim; i++)
        fac[i] = mul (fac[i - 1], i);
    inv[lim] = pow (fac[lim], mod - 2);
    for (int i=lim - 1; i>=1; i--)
        inv[i] = mul (inv[i + 1], i + 1);
}

int comb (int N, int K)
{
    int ans = mul (fac[N], inv[N - K]);
    ans = mul (ans, inv[K]);
    return ans;
}

