/*ここではaのb乗をpで割った余りを返す*/
ll calc(ll a,ll b,ll p){

    if(b == 0){
        return 1;
    }else if(b % 2 == 0){
        ll tmp = (calc(a,b/2,p)) % p;
        return ((tmp%p)*(tmp%p))%p;
    }else{
        return ((a%p)*(calc(a,b-1,p)%p)) % p;
    }
}

