template <typename T>
T power(const T &a, long long n, const T &e){
  T ret = e;
  T beki = a;
  for(long long i = 1LL; i <= n; i <<= 1){
    if( (n & i) > 0 )
      ret *= beki;
    beki = beki * beki;
  }
  return ret;
}

const int MOD = 1e9+7;
class Z_nZ {
public:
  long long m;
  Z_nZ() { ; }
  Z_nZ(long long v){
    if(v < 0)
      m = v + (- v / MOD + 1) * MOD;
    else
      m = v;
    m %= MOD;
  }
  Z_nZ operator + (const Z_nZ &a){ return Z_nZ( m + a.m ); }
  Z_nZ operator - (const Z_nZ &a){ return Z_nZ( m - a.m ); }
  void operator += (const Z_nZ &a){ m = (m + a.m) % MOD; }
  void operator -= (const Z_nZ &a){ m = (m - a.m + MOD) % MOD; }
  Z_nZ operator * (const Z_nZ &a){ return Z_nZ( m * a.m ); }
  void operator *= (const Z_nZ &a){ m = (m * a.m) % MOD; }
  Z_nZ pow(int k){ return power( Z_nZ(m), k, Z_nZ(1) ); }
  Z_nZ inv(){ return this->pow( MOD - 2 ); }
  Z_nZ operator / (Z_nZ a){ return Z_nZ( m * a.inv().m ); }
  void operator /= (Z_nZ a){ m = (m * a.inv().m) % MOD; }
  friend ostream& operator << (ostream& os, const Z_nZ & a);  
};
ostream& operator << (ostream& os, const Z_nZ & a){
  os << a.m;
  return os;
};
Z_nZ factorial(long long n){
  Z_nZ ret(1);
  for(int i = 2; i <= n; i++) ret *= Z_nZ( i );
  return ret;
}
Z_nZ binomial(long long a, long long b){
  Z_nZ ret(1);
  for(int i = a; i > a - b; i--)
    ret *= Z_nZ( i );
  ret /= factorial( b );
  return ret;
}

