inline ull ksm (int x, int y) {
    ull bs = x, ans = 1;
    while (y) {
        if (y & 1) ans *= bs;
        if (ans >= mod) ans %= mod;
        bs *= bs;
        if (bs >= mod) bs %= mod;
        y >>= 1;
    }
    return ans;
}

inline ull C (int x, int y) {
    ull a1 = 1;
    if (y < x - y) y = x - y;
    for (int i = y + 1; i <= x; i++) {
        a1 *= i;
        if (a1 >= mod) a1 %= mod;
    }
    ull b1 = 1;
    for (int i = 1; i <= x - y; i++) {
        b1 *= i;
        if (b1 >= mod) b1 %= mod;
    }
    b1 = ksm(b1, mod-2);
    return (a1 * b1) % mod;
}

int main() {
    scanf("%d %d %d %d", &h, &w, &A, &B);
    ull ans = 0;
    for (int i = B; i <= w - 1; i++) {
        ans += (C(i+h-A-1,i)*C(A-1+w-i-1,A-1)) % mod;
    }
    printf("%llu",ans);
    return 0;
}

