int pw(int n, int m, int base) {
    if (m==0) return 1;
    if (m%2==0) {
        int g=pw(n,m/2,base);
        return (1ll*g*g)%base;
    }
    else {
        int g=pw(n,m-1,base);
        return (1ll*n*g)%base;
    }
}
int cnk(int n, int k) {
    int a=f[n];
    int b=(1ll*f[k]*f[n-k])%base;
    a=(1ll*a*pw(b,base-2,base))%base;
    return a;
}
int get_path(int h, int w) {
    int moves=h+w-2;
    return cnk(moves,w-1);
}
