ll mpow(ll x, ll n, ll acc = 1) {
    if (n == 0) return acc;

    if (n % 2 == 0) return mpow(x * x % mod, n >> 1, acc);
    else            return mpow(x, n - 1, acc * x % mod);
}

int main() {
    ll H, W, A, B; cin >> H >> W >> A >> B;
    ll MAX_N = H + W + 4;

    vector<ll> fct(MAX_N, 1);
