#define inf 1000000007
struct Combinations {

    long long mod;
    vector< long long > inv;
    vector< long long > fact;
    vector< long long > inv_fact;

    Combinations (int n, int m) : inv(n), fact(n), inv_fact(n), mod(m) {
        inv[1] = 1;
        for (long long i = 2; i < n; i++) {
            inv[i] = inv[mod%i] * (mod - mod / i) % mod;
        }
        fact[0] = inv_fact[0] = 1;
        for (long long i = 1; i < n; i++) {
            fact[i] = (fact[i-1] * i) % mod;
            inv_fact[i] = (inv_fact[i-1] * inv[i]) % mod;
        }
    }

    long long nPr(long long n, long long r) {
        if (n < r || r < 0) return 0;
        return fact[n] * inv_fact[n-r] % mod;
    }

    long long nCr(long long n, long long r) {
        if (n < r || r < 0) return 0;
        return nPr(n,r) * inv_fact[r] % mod;
    }

    long long nHr(long long n, long long r) {
        return nCr(n+r-1,r);
    }

};
/*
 usage:
 O(N);
 Combination C(N,inf);//Nまでの全てのcombination, %inf;
 C.nCr(a,b); // aCbの値
 C.nPr,  C.nHrなどもある
 */

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll H,W,A,B; cin >> H >> W >> A >> B;
    Combinations C(100000, inf);

    vector<pair<ll,ll> > F,T;
    rep(i,W){
        if(B+1+i > W) break;
        F.pb(mp(H-A  , B+1+i));
        T.pb(mp(H-A+1, B+1+i));
    }

    ll ans = 0;
    for(ll i = 0; i< F.size(); i++){
        ll ret = 0;
        ret += C.nCr((F[i].first -1)+(F[i].second -1), (F[i].first -1));
        ret *= C.nCr( (H-T[i].first)+(W-T[i].second),(H-T[i].first) );
        ret %= inf;
        ans += ret;
        ans %= inf;
    }

    cout << ans << endl;


    //cout << fixed << setprecision(16) << ans << endl;
    return 0;
}

