const ll INF = static_cast<ll>(1e9) + 7ll;
const ll LINF = INF * INF;
const int MAXN = static_cast<int>(1e6) + 17;

int n, m, a, b;
ll fac[MAXN];

bool read() {
    if (!(cin >> n >> m >> a >> b))
        return false;

    return true;
}

ll binpow(ll a, ll n) {
    ll res = 1ll;

    for (; n > 0; n /= 2, a = a * a % INF)
        if (n & 1)
            res = res * a % INF;

    return res;
}

ll rev(ll x) { return binpow(x, INF - 2); }

ll binomial(int n, int k) {
    return fac[n] * rev(fac[k] * fac[n - k] % INF) % INF;
}

void solve() {
    fac[0] = 1;

    forn (i, MAXN - 1)
        fac[i + 1] = (i + 1) * fac[i] % INF;

    int j = b - 1;
    ll ans = 0;

    for (int i = 0; i + a < n; ++i) {
        ans += binomial(i + j, i) * binomial(n - i + m - j - 3, n - i - 1);
        ans %= INF;
    }

    cout << ans << endl;
}

int main() {
    cin.tie(nullptr);
    std::ios_base::sync_with_stdio(false);

    while (read())
        solve();

    return 0;
}

