		if(i==0){
			xpow[i]=x;
			c[i]=1;
		}else{
			xpow[i]=xpow[i-1]*xpow[i-1]%MOD;
			c[i]=c[i-1]*2;
		}
	}
	long long int r=MOD-2, xinv=1;
