int mod_pow(int x,int k,int mod){
  if(k==0)return 1;
  if(k==1)return x;
  int ret = 1;
  while(k){
    if(k&1)ret=ret*x%mod;
    x=x*x%mod;
    k>>=1;
  }
  return ret;
}

int mod_comb(int n,int r,int mod){
  if(r>n-r)r=n-r;
  if(r==0)return 1;
  int a=1;
  FOR(i,0,r)a=a*((n-i)%mod)%mod;
  int b=mod_pow(mod_fact(r,mod),mod-2,mod);
  return (a%mod)*(b%mod)%mod;
}

