long modfact[200000];
long modfactinv[200000];

long power(long x, long n) {
    if (n == 0) return 1;
    if (n == 1) return x;
    if (n % 2 == 0) {
        long t = power(x, n / 2);
        return t * t % MOD;
    }
    long t = power(x, n / 2);
    return x * t % MOD * t % MOD;
}

long choose(int n, int r) {
    return modfact[n] * modfactinv[r] % MOD * modfactinv[n - r] % MOD;
}

int main() {
