      inv[i] = inv[i + 1] * (i + 1) % m;
    }
    */

  }
  ll mod_pow(ll x, ll n) {
    ll ans = 1;
    while (n > 0) {
      if ((n & 1) == 1) ans = ans * x % m;
      x = x * x % m;
      n >>= 1;
    }
    return ans;
  }
  ll factorial(int n) {
    return fact[n];
  }
  ll comb(int n, int k) {
    return fact[n] * inv[k] % m * inv[n - k] % m;
  }
};

