#define MOD 1000000007
#define INF 1000000000
#define MAX_N 200010

// 二次元のマス目を左上から右下へ移動するときのパターン数
// DP で考えると各マス目にパスカルの三角形が現れることがわかる
// つまり組み合わせで、 nCr の形で表すことができることがわかる
// nCr は今回は n = H-1+W-1, r = W-1(またはH-1) となる
// A, B で制限された領域の直前のところの nCr をもとめ、
// そこから一つ下への移動は 1 パターン。
// そこから左下へまた nCr を使って組み合わせを求め、
// それらの積を各列に関して足した和が答え

ll H, W, A, B;

// 0! ～ N! までの階乗を保管する配列の作成 (mod MOD をとってある)
// O(n)
// 大体 N <=10^5 && 10^9+7 の mod を求める時に必要になるはず
// fact[i] で i! にアクセス
ll fact[MAX_N];
ll fact_inv[MAX_N];
ll N;  // あらかじめ N に値を入れておく

// x の n 乗 を m で余りをとったもの
ll mod_pow(ll x, ll n, ll mod) {
    ll res = 1;
    while ( n > 0) {
        if (n & 1) { res = res * x % mod; } // 最下位ビットが立っているときに x^(2^i) を掛ける
        x = x * x % mod;                    // x を順次 2 乗していく
        n >>= 1;
    }
    return res;
}

// nCr
ll combination(ll n, ll r, ll mod) {
    assert(n <= N);
    assert(r <= n);
    ll ret = (fact[n] * fact_inv[n - r]) % mod;
    ret = (ret * fact_inv[r]) % mod;
    return ret;
}
ll combination(ll n, ll r) {
    return combination(n, r, MOD);
}

int main()
{
    cin >> H >> W >> A >> B;

    N = H + W;

    // 階乗の作成
    fact[0] = 1;
    for(int i = 1; i <= N; ++i) {
        fact[i] = (fact[i-1] * i) % MOD;
    }
    // N! の逆元 1/N! を二分累乗法で求める
    // フェルマーの小定理より a^-1 = a^(p-2) mod p -> (N!)^-1 = (N!)^(p-2) mod p
    fact_inv[N] = mod_pow(fact[N], MOD-2, MOD);     // mod_pow の定義は↑の方にある
    // 以下 1 / (N-1)! = N / N! であることを利用
    for(int i = N - 1; i >= 0; --i) {
        fact_inv[i] = (fact_inv[i + 1] * (i + 1)) % MOD;
    }

    ll ans = 0;
    for(ll i = B + 1; i <= W; ++i) {
        ll tmp_h = H - A;
        ll tmp_w = W - i + 1;
        ll pat1 = combination(i - 1 + tmp_h - 1, i - 1);
        pat1 %= MOD;
        ll pat2 = combination(tmp_w - 1 + A - 1, tmp_w - 1);
        pat2 %= MOD;
        ans += pat1 * pat2;
        ans %= MOD;
    }
    printf("%lld\n", ans);

    return 0;
}

