  int h, w, a, b;
  cin >> h >> w >> a >> b;
  int const MOD = (int) 1e9 + 7;

  auto mul = [](i64 x, int y) {
    return (int) (x * y % MOD);
  };
  auto add_self = [](int& x, int y) {
    x += y;
    if (x >= MOD) {
      x -= MOD;
    }
  };
  auto pw = [&](int n, i64 deg) {
    int r = 1;
    while (deg) {
      if (deg & 1) {
        r = mul(r, n);
      }
      n = mul(n, n);
      deg >>= 1;
    }
    return r;
  };
  auto inv = [&](int n) {
    return pw(n, MOD - 2);
  };

  int const N = 2 * max(h, w) + 2;
  vector<int> fact(N + 1), rfact(N + 1);
  fact[0] = 1;
  for (int i = 1; i <= N; ++i) {
    fact[i] = mul(i, fact[i - 1]);
  }
  rfact[N] = inv(fact[N]);
  for (int i = N - 1; i >= 0; --i) {
    rfact[i] = mul(rfact[i + 1], i + 1);
  }

  auto choose = [&](int n, int k) {
    return mul(fact[n], mul(rfact[k], rfact[n - k]));
  };
  auto ways = [&](int r1, int c1, int r2, int c2) {
    int dr = r2 - r1;
    int dc = c2 - c1;
    return choose(dr + dc, dr);
  };
  int ans = 0;
  for (int r = 0; r < h - a; ++r) {
    add_self(ans, mul(ways(0, 0, r, b - 1), ways(r, b, h - 1, w - 1)));
  }
  cout << ans << '\n';

#ifdef GOLIKOV
