const int MOD = 1e9 + 7;

void ModSum(int& x, int y) {
    x += y;
    if (x >= MOD) {
        x -= MOD;
    }
    if (x < 0) {
        x += MOD;
    }
}

void ModMul(int& x, int y) {
    x = (1LL * x * y) % MOD;
}

int GetBinaryPow(int x, int pw) {
    int r = 1;
    while (pw > 0) {
        if (pw & 1) {
            ModMul(r, x);
        }
        ModMul(x, x);
        pw >>= 1;
    }
    return r;
}

int GetInv(int x) {
    return GetBinaryPow(x, MOD - 2);
}

const int MAX_FACT = 3e5;

int fact[MAX_FACT];
int invFact[MAX_FACT];

void BuildFact() {
    fact[0] = 1;
    for (int i = 1; i < MAX_FACT; ++i) {
        fact[i] = fact[i - 1];
        ModMul(fact[i], i);
    }
    for (int i = 0; i < MAX_FACT; ++i) {
        invFact[i] = GetInv(fact[i]);
    }
}

int GetC(int n, int k) {
    if (k > n) {
        return 0;
    }
    int r = fact[n];
    ModMul(r, invFact[n - k]);
    ModMul(r, invFact[k]);
    return r;
}

int GetCount(int fx, int fy, int tx, int ty) {
    int dx = tx - fx;
    int dy = ty - fy;
    return GetC(dx + dy, dx);
}

int main() {
    BuildFact();

    int h, w, a, b;
    scanf("%d%d%d%d", &h, &w, &a, &b);

    int result = GetCount(0, 0, h - 1, w - 1);
    for (int i = 0; i < b; ++i) {
        int curResult = GetCount(0, 0, h - a - 1, i);
        ModMul(curResult, GetCount(h - a, i, h - 1, w - 1));

        ModSum(result, -curResult);
    }

    printf("%d\n", result);

    return 0;
}

