typedef math::modulo_number<1000000007> number_t;
std::vector<number_t> check(std::vector<number_t>const& data, std::size_t H)
{
	int W = data.size();
	std::vector<number_t> inside = { data[0] };
	std::vector<number_t> ret{};
	for (int i = 1;i < H + W - 1;++i)
	{
		std::vector<number_t> impl;
		int index{};
		if (i < W)
		{
			impl.emplace_back(data[i]);
		}
		if (i >= H)
		{
			ret.emplace_back(inside.back());
		}
		for (int y = 1;y < H;++y)
		{
			int x = i - y;
			if (x >= W)
				continue;
			if (x < 1)
				break;
			++index;
			impl.emplace_back(inside[index] + inside[index - 1]);
		}
		if (i < H)
		{
			impl.emplace_back(data[0]);
		}
		std::swap(impl, inside);
	}
	ret.emplace_back(inside.back());
	return ret;
}

