long long bigmod(long long a, long long p){
    if(p == 0){
        return 1;
    }
    long long ans = bigmod(a, p/2);
    ans = (ans * ans) % mod;
    if(p % 2 == 1){
        ans = (ans * a) % mod;
    }
    return ans;
}
long long per(long long a, long long b){
    long long cur = (fact[b] * fact[a]) % mod;
    cur = bigmod(cur, mod - 2);
    cur = (cur * fact[a + b]) % mod;
    return cur;
}
