    for(int i=0; i<min(a, b); ++i){
        int y = h - a + i;
        int x = b - i - 1;
        ans = ans - combination(y + x, y) * combination((h - 1 - y) + (w - 1 - x), h - 1 - y);
    }
    cout << ans.getValue() << endl;

    return 0;
}

