    bool table[h][w];
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            table[i][j] = !(h - i <= a && j < b);
        }
    }
    int dp[h][w];
    for (int j = 0; j < w; j++) {
        dp[0][j] = (table[0][j]) ? 1 : 0;
    }
    for (int i = 1; i < h; i++) {
        dp[i][0] = (table[i][0]) ? 1 : 0;
        for (int j = 1; j < w; j++) {
            if (table[i][j])
                dp[i][j] = (dp[i][j - 1] + dp[i - 1][j]) % BASE;
            else
                dp[i][j] = 0;
        }
    }
    cout << dp[h - 1][w - 1] << endl;
    return 0;
}

