int invtable[200001];

int power(int n, int p) {
    if (p == 0)
        return 1;
    long long res = 1;
    long long add = n;
    while (p > 0) {
        if (p & 1)
            res = (res * add) % MOD;
        p >>= 1;
        add = add*add%MOD;
    }
    return res;
}

int getinv(int n) {
    if (invtable[n])
        return invtable[n];
    return invtable[n] = power(n, MOD - 2);
}

int comb(int n, int r) {
    long long res = 1;
    for (int i = 1; i <= n; i++)
        res = (res *i) % MOD;
    for (int i = 1; i <= n - r; i++)
        res = (res * getinv(i)) % MOD;
    for (int i = 1; i <= r; i++)
        res = (res * getinv(i)) % MOD;

    return res;
}

