int H, W, A, B;

long long fact[200010];

inline long long madd(long long a, long long b) { return (a+b) % MOD; }
inline long long mmul(long long a, long long b) { return (a*b) % MOD; }

long long mpow(long long a, long long p) {
    if (p == 0) return 1;
    if (p == 1) return a;
    long long half = mpow(a, p/2);
    long long ret = mmul(half, half);
    if (p % 2) ret = mmul(ret, a);
    return ret;
}

long long bino(int n, int k) {
    long long ret = 1;
    while (n || k) {
        long long nn = n % MOD, kk = k % MOD;
        if (nn < kk) return 0;
        ret = mmul(ret, fact[nn]);
        ret = mmul(ret, mpow(mmul(fact[kk], fact[nn-kk]), MOD-2));
        n /= MOD, k /= MOD;
    }
    return ret;
}

long long count(int r, int c) {
    return bino(r+c, min(r, c));
}

long long solve() {
    fact[0] = 1;
    for (int n = 1; n < 200010; n++) fact[n] = mmul(fact[n-1], n);
    long long ret = 0;
    for (int r = 1; r <= H-A; r++)
        ret = madd(ret, mmul(count(r-1, B-1), count(H-r, W-B-1)));
    return ret;
}

