int MOD = 1000000007;
map<pair<int,int>, multiprecision::cpp_int>memo;

int combination(int a, int b) {

	if (b != min(b, a - b))return combination(a, a - b);

	auto itr = memo.find(make_pair(a, b));
	if (itr != memo.end())return itr->second.convert_to<int>() % MOD;

	itr = memo.find(make_pair(a, b - 1));
	if (itr != memo.end()) {
		auto num = itr->second;
		num *= a - b + 1;
		num /= b;
		memo[make_pair(a, b)] = num;
		return num.convert_to<int>() % MOD;
	}


	itr = memo.find(make_pair(a, b + 1));
	if (itr != memo.end()) {
		auto num = itr->second;
		num *= b + 1;
		num /= a - b;
		memo[make_pair(a, b)] = num;
		return num.convert_to<int>() % MOD;
	}

	multiprecision::cpp_int answer = 1;
	rep(i, b) {
		answer *= a - i;
		answer /= 1 + i;
	}
	memo[make_pair(a, b)] = answer;
	return answer.convert_to<int>() % MOD;
}

signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int H, W, A, B;
	cin >> H >> W >> A >> B;

	int edgeh = H - A - 1;
	int edgew = B;
	int result = 0;
	while (0 <= edgeh && edgew < W) {
		//初期位置からedgeまでのパターン
		int ans1 = combination(edgeh + edgew, edgeh);

		//edgeからゴールまでのパターン
		int ans2 = combination(H - edgeh + W - edgew - 2, H - edgeh - 1);

		result += (ans1 * ans2) % MOD;
		result %= MOD;

		edgeh--;
		edgew++;
	}
	cout<<result<<endl;
}

