struct modint {
  int v;
  modint(long long v_ = 0): v(v_ % MOD) { }
  modint operator+ (modint other) {
    return modint(v + other.v);
  }
  modint operator- (modint other) {
    return modint(v - other.v + MOD);
  }
  modint operator* (modint other) {
    return modint((lint)v * other.v % MOD);
  }
  modint operator+= (modint other) {
    (v += other.v) %= MOD;
    return *this;
  }
  modint operator*= (modint other) {
    v = ((lint)v * other.v) % MOD;
    return *this;
  }
  modint operator-= (modint other) {
    (v += MOD - other.v) %= MOD;
    return *this;
  }
};

