struct segT{
	LL arr[3000005];
	int l[3000005],r[3000005];
	void Init(int p,int L,int R){
		l[p]=L;
		r[p]=R;
		if(L!=R){
			int m=(L+R)>>1;
			Init((p<<1),L,m);
			Init(((p<<1)|1),m+1,R);
			arr[p]=arr[(p<<1)]*arr[((p<<1)|1)];
			arr[p]%=MOD;
		}
		else {
			arr[p]=(LL)L;
		}
	}
	LL getv(int p,int L,int R){
		if(l[p]>=L && r[p]<=R){
			return arr[p];
		}
		int m=(l[p]+r[p])>>1;
		LL ret=1;
		if(L<=m) ret=getv((p<<1),L,R);
		if(R>m) ret*=getv(((p<<1)|1),L,R);
		ret%=MOD;
		return ret;
	}
}segt;
LL multiply(LL val,int times){
	LL res=1;
	while(times){
		if(times&1) {
			res*=val;
			res%=MOD;
		}
		val*=val;
		val%=MOD;
		times>>=1;
	}
	return res;
}
LL GC(int N,int M){
	if(N<M) return 0;
	if(M==0) return 1;
	LL s1,s2,s3;
	s1=multiply(segt.getv(1,1,MIN(M,N-M)),(int)MOD-2);
	s2=multiply(segt.getv(1,MIN(M,N-M)+1,MAX(M,N-M)),(int)MOD-1);
	s3=multiply(segt.getv(1,MAX(M,N-M)+1,N),(int)MOD);
	s1*=s2;
	s1%=MOD;
	s1*=s3;
	s1%=MOD;
	return s1;
}
LL getv(int xx,int yy,int nn,int mm){
	return GC(nn+mm-xx-yy,mm-yy);
}
