ll comb(ll cb_l, ll cb_r) {
    // nCrとして，cb_l: n, cb_r: r
    ll comb = 1;
    if (cb_l < cb_r || cb_l < 0 || cb_r < 0) comb = 0;
    else {
    	for (int i = 1; i <= cb_r; i++) {
    		comb *= (cb_l - i + 1);
    		comb /= i;
    		if (comb > inf) comb %= inf;
    	}
    }
    return comb;
}

