//(x^m) % p
long long int mul(long long int x, long long int m, long long int p)
{
	long long int ans = 1;

	while (m > 0)
	{
		if (m % 2 != 0)
		{
			ans *= x;
			ans %= p;
		}

		x *= x;
		x %= p;
		m /= 2;
	}
	return ans;
}

