typedef long long LL;
const int md = 1e9 + 7;
const int maxn = 2e5 + 5;
LL fact[maxn], inv[maxn];

LL quick_pow(LL a, LL k){
    LL ans = 1;
    while(k){
        if(k & 1) ans = ans * a % md;
        a = a * a % md;
        k >>= 1;
    }
    return ans;
}

void init(){
    fact[0] = inv[0] = 1;
    for(int i = 1; i < maxn; i++){
        fact[i] = fact[i - 1] * i % md;
        inv[i] = inv[i - 1] * quick_pow(i, md - 2) % md;
    }
}

LL C(int n, int m){
    return fact[n] * inv[m] % md * inv[n - m] % md;
}

LL path(int x1, int y1, int x2, int y2){
    return C(x2 + y2 - x1 - y1, x2 - x1);
}

int main(){
    init();
    int H, W, A, B;
    scanf("%d%d%d%d", &H, &W, &A, &B);
    LL ans = 0;
    for(int i = 1; i < H - A; i++){
        if(B + 2 <= W){
            ans += path(1, 1, i, B + 1) * path(i, B + 2, H, W) % md;
            ans %= md;
        }
    }
    if(B + 1 <= W && A){
        ans += path(1, 1, H - A, B + 1) * path(H - A + 1, B + 1, H, W) % md;
        ans %= md;
    }
    if(B + 2 <= W){
        ans += path(1, 1, H - A, B + 1) * path(H - A, B + 2, H, W) % md;
        ans %= md;
    }
    printf("%lld\n", ans);
    return 0;
}
