    using namespace mod;

    mod::Integer ans = 0;
    auto table = mod::fact_table((H + W));

    FOR (i, B, W) {
        // (0, 0) -> (H-A-1, i)
        auto r1 = table[H - A - 1 + i].value * table[H - A - 1].inverse * table[i].inverse;
        // (H-A, i) -> (H-1, W-1)
        auto h = A - 1;
        auto w = W - i - 1;
        auto r2 = table[h + w].value * table[h].inverse * table[w].inverse;
        ans += r1 * r2;
    }
    cout << ans.get() << endl;
}

