int exp(int a, int b) {
	if(b == 0)
		return 1;

	if(b & 1)
		return 1LL * a * exp(a, b - 1) % MOD;

	int sq = exp(a, b / 2);
	return 1LL * sq * sq % MOD;
}

int comb(int n, int k) {
	if(n < k)
		return 0;

	int ans = 1LL * f[n] * inv[k] % MOD;
	ans = 1LL * ans * inv[n - k] % MOD;

	return ans;
}

int ways(int f0, int c0, int f, int c) {
	return comb(f - f0 + c - c0, f - f0);
}

