#define N 212345

LL fact[N],ifact[N];

LL power(LL a,LL b)
{
    LL rs = 1,cr = a;
    while(b)
    {
        if(b&1) rs = (rs*cr)%mod;
        cr =  (cr*cr)%mod;
        b >>= 1;
    }
    return rs;
}

LL ncr(int n,int r)
{
    LL rs = fact[n];
    rs *= ifact[r];
    rs %= mod;
    rs *= ifact[n-r];
    return rs%mod;
}

void solve()
{
    int h,w,a,b,i;
    sd(h);
    sd(w);
    sd(a);
    sd(b);
    fact[0] = 1;
    for(i=1;i<N;++i)
        fact[i] = (fact[i-1]*i)%mod;
    ifact[N-1] = power(fact[N-1],mod-2);
    for(i=N-2;i>=0;--i)
        ifact[i] = (ifact[i+1]*(i+1))%mod;
    LL rs = 0;
    //cout << ifact[0] << endl;
    for(i=0;i<(h-a);++i)
    {
        rs += (ncr(b-1+i,i)*ncr(w-1-b+h-1-i,h-1-i));
        rs %= mod;
    }
    printf("%lld\n",rs);
}

