const ll P = (ll)1e9 + 7;

ll powmod(ll x, ll n) {
	x %= P;
	ll res = 1;
	while (n) {
		if ((n & 1)) {
			res = (res * x) % P;
			n--;
		}
		else {
			x = (x * x) % P;
			n >>= 1;
		}
	}
	return res;
}

const int N = 400500;

ll fact[N], invFact[N];

void calc() {
	fact[0] = invFact[0] = 1;
	for (int i = 1; i < N; i++) {
		fact[i] = (fact[i - 1] * i) % P;
		invFact[i] = powmod(fact[i], P - 2);
	}
}

ll C(int n, int k) {
	if (k > n) return 0;
	return fact[n] * invFact[k] % P * invFact[n - k] % P;
}

ll ways(int x, int y, int xx, int yy) {
	if (x > xx || y > yy) return 0;
	return C(xx - x + yy - y, xx - x);
}

