template<typename T>
T exgcd(T a, T b, T& x, T& y)
{
	if (a == 0 && b == 0)return -1;
	if (b == 0) { x = 1, y = 0; return a; }
	T d = exgcd(b, a % b, y, x);
	y -= a / b * x;
	return d;
}
template<typename T>
T inv1(T a,T Mod=mod)
{
	T x, y;
	return exgcd(a, Mod, x, y) == 1 ? (x % Mod + Mod) % Mod : -1;
}
auto inv2 = [](auto a, auto Mod) {return poww(a, Mod - 1, Mod); };
template<typename T>
constexpr T _gcd(T a, T b)
{
