	ll ans = cmb(H+W-2, H-1);
	//cout << ans << endl;
	reps(i,1,A+1){
		ll a = cmb(H-i+B-1, B-1);
		ll b = cmb(i-1+W-B-1, W-B-1);
		//cout << -a*b << endl;
		ans = (ans + MOD - (a*b)%MOD) % MOD;
	}

	cout << ans << endl;

	return 0;
}

