int64_t expotent(int64_t n,int64_t m){
  if (m == 1) return n;
  else if (m % 2 == 0) return expotent(n * n % MOD, m/2);
  else return expotent(n * n % MOD, m/2) * n % MOD;
}

int64_t nCr(int64_t n, int64_t r){
  int Ans = 1;  
  if (r > n / 2) r = n - r;
  for (int i = 1; i <= r; i++)
    Ans = Ans * (n + 1 - i) % MOD * expotent(i, MOD-2) %MOD;

  return Ans;
}

