    // c = comb(h - a + i - 1, h - a - 1) * comb(a + w - i - 2, a - 1) % M;
    if (i == 0) {
      c = comb(h - a - 1, h - a - 1) * comb(a + w - 2, a - 1) % M;
    } else {
      c = c * (h - a + i - 1) % M * inv(i, M) % M;
      c = c * (w - i) % M * inv(a + w - i - 1, M) % M;
    }
    ans = (ans + M - c) % M;
  }
  std::cout << ans << std::endl;
  return 0;
}

