#define MAX_X (30)
#define MAX_Y (30)

uint32_t pascals_triangle_mod_m(const uint32_t i, const uint32_t j, const uint32_t m)
{
    uint32_t tbl1[MAX_X * MAX_Y + 1];
    uint32_t tbl2[MAX_X * MAX_Y + 1];
    uint32_t *cur_tbl, *prv_tbl;

    tbl1[0] = 1;
    prv_tbl = tbl1;
    cur_tbl = tbl2;
    for (uint32_t row = 1; row <= i; row++) {
        for (uint32_t col = 0; col <= row; col++) {
            if (col == 0 || col == row) {
                cur_tbl[col] = 1;
            } else {
                cur_tbl[col] = (prv_tbl[col - 1] + prv_tbl[col]) % m;
            }
        }
        if (row < i) {
            if (cur_tbl == tbl1) {
                cur_tbl = tbl2;
                prv_tbl = tbl1;
            } else {
                cur_tbl = tbl1;
                prv_tbl = tbl2;
            }
        }
    }
    return cur_tbl[j];
}

uint32_t combination_mod_m(const uint32_t n, const uint32_t r, const uint32_t m)
{
    return pascals_triangle_mod_m(n, r, m);
}

uint32_t sub_mod_m(uint32_t a, uint32_t b, const uint32_t m)
{
    if (a < m) {
        a += m;
    } else {
        a %= m;
    }

    if (b >= m) {
        b %= m;
    }

    return (a - b) % m;
}

int main(void)
{
    uint32_t H, W, A, B;
    scanf("%u %u %u %u", &H, &W, &A, &B);

