    uint32_t pat2 = combination_mod_m(H-A+B-1, H-A, 1000000007);
    // printf("pat1 = %u\n", pat1);
    // printf("pat2 = %u\n", pat2);
    uint32_t ans = sub_mod_m(pat1, pat2, 1000000007);

    printf("%u\n", ans);

    return 0;
}

