LL quickmi(LL b,LL p,LL k)
{
	if(!p)return 1;
	LL ans=1,tmp=b;
	while(p)
	{
		if(p&1)ans=ans*tmp%k;
		tmp=tmp*tmp%k;
		p>>=1;
	}
	return ans%k;
