const int mod = 1e9 + 7;
const int N = 2e5 + 5;
int add(int a , int b){
	int res = a + b;
	if(res >= mod){
		return res - mod;
	}
	return res;
}
int mult(int a , int b){
	long long res = a;
	res *= b;
	if(res >= mod){
		return res % mod;
	}
	return res;
}
int power(int a , int b){
	int res = 1;
	while(b){
		if(b & 1){
			res = mult(res , a);
		}
		a = mult(a , a);
		b >>= 1;
	}
	return res;
}
int fact[N];
int ifact[N];
void pre(){
	fact[0] = 1;
	for(int i = 1 ; i < N ; ++i){
		fact[i] = mult(fact[i - 1] , i);
	}
	ifact[N - 1] = power(fact[N - 1] , mod - 2);
	for(int i = N - 2 ; i >= 0 ; --i){
		ifact[i] = mult(ifact[i + 1] , i + 1);
	}
}
int ncr(int n , int r){
	return mult(fact[n] , mult(ifact[r] , ifact[n - r]));
}
int n , m , a , b;
int ans;
int ways(int x1 , int y1 , int x2 , int y2){
	return ncr(x2 + y2 - x1 - y1 , x2 - x1);
}
