#define FAC 1000000007

int gcd(int a, int b){
	if(a==0) return b;
	return gcd(b%a, a);
}

unsigned long long calc(int x, int y, int H, int W){
	int x1 = x;
	int y1 = H-1-y;
	int x2 = W-1-x;
	int y2 = y;

	vector<int> den, num;
	vector<int>::iterator itr_d, itr_n;
	int g;
	if(x1<y1) swap(x1, y1);
	if(x2<y2) swap(x2, y2);
	for(int i=1; i<=y1; i++){
		num.push_back(x1+i);
		den.push_back(i);
	}
	for(itr_d=den.begin(); itr_d!=den.end(); itr_d++){
		for(itr_n=num.begin(); itr_n!=num.end(); itr_n++){
			g = gcd(*itr_d, *itr_n);
			*itr_d /= g; *itr_n /= g;
			if(*itr_d==1) break;
		}
	}
	for(int i=1; i<=y2; i++){
		num.push_back(x2+i);
		den.push_back(i);
	}
	for(itr_d=den.begin(); itr_d!=den.end(); itr_d++){
		for(itr_n=num.begin(); itr_n!=num.end(); itr_n++){
			g = gcd(*itr_d, *itr_n);
			*itr_d /= g; *itr_n /= g;
			if(*itr_d==1) break;
		}
	}
	unsigned long long res = 1;
	for(itr_n=num.begin(); itr_n!=num.end(); itr_n++){
		res = (res * *itr_n) % FAC;
	}
	return res;
}


