struct Mod_nCm {
    ll MAX, MOD;
    vector<ll> fac, finv, inv;
    Mod_nCm(ll max, ll mod): MAX(max+1), MOD(mod), fac(MAX), finv(MAX), inv(MAX) {
        fac[0] = fac[1] = 1;
        finv[0] = finv[1] = 1;
        inv[1] = 1;
        for (int i = 2; i < MAX; i++){
            fac[i] = fac[i - 1] * i % MOD;
            inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
            finv[i] = finv[i - 1] * inv[i] % MOD;
        }
    }
    ll get_nCm(ll n, ll m) {
        if (n > MAX) return -1;
        if (n < m) return 0;
        if (n < 0 || m < 0) return 0;
        return fac[n] * (finv[m] * finv[n - m] % MOD) % MOD;
    }
};

