  for(long long i = b; i < w; ++i) {
    now = calccomb(h - 1 - a + i, i) - bf;
    while(now < 0) now += N;
    ans += now * calccomb(a + w - 1 - i, a) % N;
    ans %= N;
    bf = calccomb(h - 1 - a + i, i);
  }
  return ans;
}

