ll power(ll n, ll p, ll m) {
	if (n == 0) { return 0; }
	if (p == 0) { return 1; }
	if (p == 1) { return n%m; }
	if (p & 1) {
		ll y = power(n, (p - 1) / 2, m);
		y = (y*y) % m;
		return (n*y) % m;
	}
	else {
		ll y = power(n, p / 2, m);
		y = y*y%m;
		return y;
	}
}
