	vl inv(M+1), iperm(M+1), perm(M+1);
	for (ll i = 1; i <= M; i++) {
		inv[i] = power(i, mod - 2, mod);
	}
	perm[0] = 1;
	iperm[0] = inv[1];
	iperm[1] = inv[1];
	perm[1] = 1;
	for (ll i = 2; i <= M; i++) {
		iperm[i] = (inv[i] * iperm[i - 1]) % mod;
		perm[i] = (i*perm[i - 1]) % mod;
	}

	vl memo(H - A,0);
	for (ll y = 0; y < H - A; y++) {
		ll n = (B-1 + y+mod)%mod;
		ll mem = perm[n] * iperm[y] % mod;
		mem = mem*iperm[n - y] % mod;
		memo[y] = mem;
	}

	ll ans = 0;
	for (ll y = 0; y < H - A; y++) {
		ll ny = (W - 1 - (B) + mod) % mod;
		ll nx = (H - 1 - y + mod) % mod;
		ll n = (nx+ny)%mod;
		ll d = perm[n] * iperm[ny] % mod;
		d = d*iperm[nx] % mod;
		d = d*memo[y] % mod;
		ans = (ans + d) % mod;
	}

	cout << ans << endl;
	return 1;
}

