LL F[N], IF[N];

LL _pow(LL a, LL b) {
  if(!b) return 1;
  if(b == 1) return a;
  if(b == 2) return a * a % mod;
  if(b & 1) {
    return a * _pow(a,b-1) % mod;
  }
  return _pow(_pow(a,b/2),2);
}

void pre() {
  F[0] = 1;
  rep(i,1,N) {
    F[i] = F[i-1] * i % mod;
  }
  IF[N-1] = _pow(F[N-1], mod-2);
  for(int i = N - 2; i >= 0; i--) {
    IF[i] = IF[i+1] * (i + 1) % mod;
  }
}

LL nCr(int n, int r) {
  if(n < r) return 0;
  return F[n] * (IF[n-r] * IF[r] % mod) % mod;
}

