const int MAX_N = 200000;
ll FACT[MAX_N + 1], IFACT[MAX_N + 1];

ll comb(ll n, ll r) {
    if (n < 0 || r < 0 || r > n)return 0;
    if (r > n / 2) r = n - r;
    return FACT[n] * IFACT[n - r] % MOD * IFACT[r] % MOD;
}

