    // 下にA-1回、右にW-B-1-i回移動する
    REP(i,W-B){
        ll tmp = COM(H-A-1+B+i,H-A-1);
        tmp *= COM(A-1+W-B-1-i,A-1);
        tmp %= MOD;
        ans = (ans + tmp) % MOD;
    }
