// Exponentiation by squaring
LL expsq(LL x, LL p) {
	LL res = 1;
	while (p > 0) {
		if (p & 1) {
			res = (res * x) % MOD;
		}
		x = (x * x) % MOD;
		p /= 2;
	}
	return res;
}

// Extended Euler's algorithm
LL modinv(LL x) {
	return expsq(x, MOD - 2);
}

LL C(LL n, LL k) {
	return (fact[n] * modinv(fact[n - k] * fact[k] % MOD)) % MOD;
}

