	for (LL i = B; i <= W - 1; i++) {
		LL res = C(H - A - 1 + i, i);
		LL end = C(W - i - 1 + A - 1, A - 1);
		res *= end;
		res %= MOD;

		ans += res;
		ans %= MOD;
	}

	cout << ans << endl;
}

