ll modpow(ll x,ll n) {
	if(n == 0) return 1;
	ll ans = 1;
	while(n > 0) {
		if((n & 1) == 1) (ans *= x) %= MOD;
		(x *= x) %= MOD;
		n >>= 1;
	}
	return ans;
}

vll modfactorial(ll m) {
	vll ret(m+1);
	ll n = 1;
	ret[0] = 1;
	FOR(i, 1, m) {
		n *= i;n %= MOD;
		ret[i] = n;
	}
	return ret;
}

vll invmodfactorial(ll m) {
	vll ret(m+1);
	ret[0] = 1;
	ll n = 1;
	FOR(i, 1, m) {
		n *= modpow(i, MOD-2);
		n %= MOD;
		ret[i] = n;
	}
	return ret;
}

ll modcomb(ll n, ll r, vll &fac, vll &inv) {
	return ((fac[n] * inv[n - r]) % MOD * inv[r]) % MOD;
}

