/**
 *
 * AtCoder Regular Contest 058 - Problem D: Iroha and the Grid
 *
 * Count the number of ways Iroha can travel from (1,1) to (H, W) in a H x W grid with bottom A 
 * rows and leftmost B columns blocked.
 *
 * Combinatorial solution: compute the number of ways that we can move from O = (1, 1) to 
 * Pk = (k, B) and multiply for the number of ways from Qk = (k, B + 1) to (H, W), 
 * for k = 1, 2, ..., H - A.
 *
 * -----------------------------------
 * |O                   |            | 
 * |                    |            | 
 * |                  Pk|Qk          | 
 * |                    |            | 
 * |                    |            | 
 * |                    |            | 
 * -----------------------------------
 * |xxxxxxxxxxxxxxxxxxxx|            |
 * |xxxxxxxxxxxxxxxxxxxx|            |
 * |xxxxxxxxxxxxxxxxxxxx|            |
 * |xxxxxxxxxxxxxxxxxxxx|           D|
 * -----------------------------------
 *
 * shape(X, Y) = dimensions of the rectangle with upper left corner A and lower right corner B
 *
 * shape(O, Pk) = (k, B)
 * shape(Qk, D) = (H - k + 1, W - B)
 *
 * The number of ways we can travel from (1, 1) to (N, M) in a rectangular grid moving right or 
 * down only is C(M + N - 2, M - 1) = C(M + N - 2, N - 1), because we must walk (M - 1) steps to 
 * right and * (N - 1) steps down, and we must choose when move forward ou move down.
 */
#include <iostream>

using namespace std;

using ll = long long;

const int MAX { 200010 };
const ll MOD { 1000000007 };

ll fact[MAX], inv[MAX];

ll fast_exp(ll a, ll n)
{
    ll res = 1, base = a;

    while (n)
    {
        if (n & 1)
        {
            res *= base;
            res %= MOD;
        }

        base *= base;
        base %= MOD;

        n >>= 1;
    }

    return res;
}

ll binom(int n, int m)
{
    ll res = (fact[n] * inv[m]) % MOD;
    res = (res * inv[n - m]) % MOD;

    return res;
}

void precomp()
{
    fact[0] = inv[0] = 1;

    for (int n = 1; n < MAX; ++n)
        fact[n] = (n * fact[n - 1]) % MOD;

    // Fermat Theorem to compute inverse mod p
    for (int n = 1; n < MAX; ++n)
        inv[n] = fast_exp(fact[n], MOD - 2);
}

// Ways we can move from (1, 1) to (h, w) 
ll ways(int h, int w)
{
    return binom(h + w - 2, h - 1);
}

int main()
{
    ios::sync_with_stdio(false);
    precomp();

    int H, W, A, B;
    cin >> H >> W >> A >> B;

    ll total = 0;

    for (int k = 1; k <= H - A; ++h)
    {
        total += (ways(k, B) * ways(H - k + 1, W - B)) % MOD;
        total %= MOD;
    }

    cout << total << endl;

    return 0;
}

