  int h, w, a, b;
  cin >> h >> w >> a >> b;
  vector<modint> factorial(h + w);
  factorial[0] = 1;
  loop(i, 1, factorial.size()) factorial[i] = modint(i) * factorial[i - 1];
  modint s = 0;
  loop(i, b, w) {
    modint x = 1;
    x *= factorial[h - a - 1 + i] / (factorial[h - a - 1] * factorial[i]);
    x *= factorial[w + a - 2 - i] / (factorial[a - 1] * factorial[w - 1 - i]);
    s += x;
  }
  cout << s << endl;
}

