        s[++top] = x % 10 + '0';
    while (top)
        putchar(s[top--]);
}
// EOT

const int MAXN = 2e5 + 5;
const int MOD = 1e9 + 7;

int H, W, A, B;

void input()
{
    read(H); read(W); read(A); read(B);
}

LL fac[MAXN], ifac[MAXN];

LL fpm(LL base, LL exp)
{
    LL ret = 1;
    for (; exp; exp >>= 1) {
        if (exp & 1)
            (ret *= base) %= MOD;
        (base *= base) %= MOD;
    }
    return ret;
}

inline LL C(int x, int y)
{
    --x; --y;
    return fac[x + y] * ifac[x] % MOD * ifac[y] % MOD;
}

void solve()
{
    int rng = H + W;
    fac[0] = 1;
    for (int i = 1; i <= rng; ++i) {
        fac[i] = fac[i - 1] * i % MOD;
    }
    ifac[rng] = fpm(fac[rng], MOD - 2);
    for (int i = rng; i >= 1; --i) {
        ifac[i - 1] = ifac[i] * i % MOD;
    }

    LL ans = C(H, W);
    for (int i = 1; i <= B; ++i) {
        (ans -= C(H - A, i) * C(A, W - i + 1)) %= MOD;
    }
    (ans += MOD) %= MOD;

    printf("%lld\n", ans);
}

int main()
{
#ifdef __DEBUG
    freopen("D.in", "r", stdin);
    freopen("D.out", "w", stdout);
#endif

    input();
    solve();
}

