LL quickmi(LL b,LL p,LL k)
{
	if(!p)return 1;
	LL ans=1,tmp=b;
	while(p)
	{
		if(p&1)ans=ans*tmp%k;
		tmp=tmp*tmp%k;
		p>>=1;
	}
	return ans%k;
}
LL C(LL n,LL m,LL k)
{
	if(n<m)return 0;
	return jc[n]*quickmi(jc[m]%k,k-2,k)%k*quickmi(jc[n-m]%k,k-2,k)%k;
}
LL Lucas(LL n,LL m,LL k)
{
	if(!m)return 1;
	return C(n%k,m%k,k)*Lucas(n/k,m/k,k)%k;
}
