// x^n % MOD
ll pow_MOD(ll x, ll n) {
    if (n == 0) return 1;
    if (n == 1) return x;

    if (n%2 == 0) {
        ll ret = pow_MOD(x, n/2);
        return (ret*ret) % MOD;
    } else {
        return (x * pow_MOD(x, n-1)) % MOD;
    }
}

