    for (int i = B + 1; i <= W; i++) {
      ll ways = mod::choose(H - A - 1 + i - 1, i - 1) *
                mod::choose(A - 1 + W - i, W - i) % MOD;
      ans = (ans + ways) % MOD;
    }
    cout << ans << endl;
  }
  return 0;
}

