		hh = a-1;
		ll tmp2 = (fact[ww + hh] * factinv[ww] % MOD) * factinv[hh] % MOD;
		//cout << tmp2 << endl;

		ans += (tmp * tmp2) % MOD;
		ans %= MOD;
	}
	cout << ans << endl;

