int mod_expo(int x, int p)
{
    if(!p)
        return 1;
    long long res = mod_expo(x, p / 2);
    res *= res;
    res %= MOD;
    if(p & 1)
        res *= x;
    return res % MOD;
}

int mod_inv(int x)
{
    return mod_expo(x, MOD - 2);
}

int nCr_mod(int n, int r)
{
    if(n < r)
        return 0;
    int num = fact[n];
    int invdenom = (invfact[r] * 1ll * invfact[n - r]) % MOD;
    return (num * 1ll * invdenom) % MOD;
}

