// a, bの最大公約数と， ax+by=gcd(a, b)となるx,yを求める
ll Extgcd(ll a, ll b, ll &x, ll &y) {
    ll g = a;
    if(b != 0) {
        g = Extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    }
    else {
        x = 1;
        y = 0;
    }

    return g;
}

// ax = gcd(a, m) (mod m) となるxを求める
// a, m が互いに素ならば関数値はmod m でのaの逆数となる
ll ModInverse(ll a, ll m)
{
    ll x, y;
    Extgcd(a, m, x, y);
    return (x % m + m) % m;
}

