  for(int j = 0; j < Hdiff; j++){
    long long Hcanmove = H - j - 1;
    long long Wcanmove = Wdiff - 1;
    pattern2[j] = COM(Hcanmove + Wcanmove, Hcanmove);
  }
  for(int k = 0; k < Hdiff; k++){
    long long patt = (pattern1[k] * pattern2[k]) % MOD;
    ans += patt % MOD;
    ans %= MOD; 
  }
  cout << ans << endl;
  return 0;
}

