template<long long mod=(int)1e9+7, int sz = 200000>
struct NCR{
  /*
    ref
    http://twilog.org/anta_prg/date-131128

    verify 
    weak
    http://arc039.contest.atcoder.jp/submissions/407546
  */

  long long fact[sz];
  long long ifact[sz];

  inline long long inv(long long p){
    long long n = mod - 2;
    long long ret = 1;
    while(n){
      if(n&1) ret = ret * p % mod;
      p = p * p % mod;
      n /= 2;
    }
    return ret;
  }

  NCR(){
    fact[0] = 1;
    for(int i = 0; i < sz; ++i){
      fact[i + 1] = fact[i] * (i + 1) % mod;
    }
    ifact[sz-1] = inv(fact[sz-1]);
    for(int i = sz - 1; i > 0; --i){
      ifact[i - 1] = ifact[i] * i % mod;
    }
  }

  long long ncr(int n, int k){
    if(n < k || k < 0) return 0;
    return fact[n] * ifact[k] % mod * ifact[n - k] % mod;
  }
};


