	ifac[mx] = qpow(fac[mx], P - 2);
	for(int i = mx; i >= 1; --i) ifac[i - 1] = 1ll * ifac[i] * i % P;
	read(a), read(b);
	for(int y = b + 1; y <= w; ++y) {
		int x = h - a;
		now[y] = C(x - 1 + y - 1, x - 1);
	}
	ll ret = 0;
	for(int y = b + 1; y <= w; ++y)
		(ret += 1ll * now[y] * C(w - y + a - 1, a - 1) % P) %= P;
	printf("%lld\n", ret);
	return 0;
}

