#define MOD 1000000007

long long int factorial[200005]={0};
long long int relay_points[100005]={0};

void set_factorial(int n){
    factorial[0] = 1;
    for(int i=1;i<=n;++i){
        factorial[i] = i * factorial[i-1] % MOD;
    }
}

long long int extgcd(long long int a, long long int b, long long int &x,
                     long long int &y) {
    long long int d = a;
    if (b != 0) {
        d = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    } else {
        x = 1;
        y = 0;
    }
    return d;
}

// a : 元, md : 法
long long int multi_inv(long long int md, long long int a) {
    long long int x, y;
    extgcd(md, a, x, y);
    return (y > 0 ? y : md + y);
}

int main(){
    long long int h, w, a, b;
    cin >> h >> w >> a >> b;

    set_factorial(h+w);

    for(int i=0;i<w-b;++i){
        long long int tmp = factorial[h-a-1+b+i];
        tmp = tmp * multi_inv(MOD, factorial[h-a-1]) % MOD;
        tmp = tmp * multi_inv(MOD, factorial[b+i]) % MOD;
        relay_points[i] = tmp;
    }

    long long int ans = 0;
    for(int i=0;i<w-b;++i){
        long long int tmp = factorial[a+w-b-i-2];
        tmp = tmp * multi_inv(MOD, factorial[a-1]) % MOD;
        tmp = tmp * multi_inv(MOD, factorial[w-b-i-1]) % MOD;
        ans = (ans + relay_points[i] * tmp % MOD) % MOD;
    }

    cout << ans << endl;

    return 0;
}

