using namespace std;

typedef unsigned long long ull;

ull m = (ull) 1e9+7;
ull dp[(ull)2e5];

ull pow(ull b, ull e){
  if(e==0) return 1;
  ull p = 1;
  if( e % 2 == 1 ){
    p = b % m;
    e--;
  }
  ull t = pow(b, e/2);
  p *= (t*t)%m;
  p %= m;
  return p;
}

ull fac(ull n){
  if( dp[n] != 0 ) return dp[n];
  if( n == 0 ) return 1;
  ull f = ((n%m)*fac(n-1)) % m;
  dp[n] = f;
  return f;
}

