class Solve{
  private:
    const int SUB_MOD = 1e9 + 5;
    int h, w, a, b;
    int for_A, for_B1, for_B2;
    Vint64 S, T;
    /* S(n) := n!を10^9 + 7 で割った余り
    *  T(n) := T(n)^(-1) = S(n)^(10^9 + 5);
    */
    int64 power(int64 n, int index){ // n^(index)を10^9 + 7で割った余りを求める
      if(index == 0) return 1;
      if(index % 2 == 0) return power((n * n) % MOD, index / 2);
      else return (n * power((n * n) % MOD, index / 2)) % MOD;
    }
    int64 calculate_inv(int n){ // n^(-1)を計算する
      return power(n, SUB_MOD);
    }
    void init_S(int k){ // Sの計算を実行する関数
      S.at(0) = 1;
      FOR(i, 1, k + 1) S.at(i) = (S.at(i - 1) * i) % MOD;
    }
    void init_T(int k){ // Tの計算を実行する関数
      T.at(0) = 1;
      FOR(i, 1, k + 1) T.at(i) = calculate_inv(S.at(i));
    }
    int64 nCr(int n, int r){ // 計算済みのS, Tを用いてnCrを10^9+7で割った余りを計算
      return ((S.at(n) * T.at(r) % MOD) * T.at(n - r)) % MOD;
    }
    int64 A(int i){ // main関数内部のコメントで定義したA(i)を計算する
      return nCr(for_A+ i, i);
    }
    int64 B(int i){ // main関数内部のコメントで定義したB(i)を計算する
      return nCr(for_B1 - i, for_B2 - i);
    }
  public:
    // コンストラクタ : 初期化および計算用のS, Tを計算しておく
    Solve(int hin, int win, int ain, int bin){
      h = hin; w = win; a = ain; b = bin;
      for_A = b-1; for_B1 = h + w - b - 2; for_B2 = h - 1;
      S.resize(h + w + 1);
      T.resize(h + w + 1);
      init_S(h + w);
      init_T(h + w);
    }
    ~Solve(){};
    int64 solve_promblem(void){ // 求める答え本体
      int64 res = 0;
      REP(i, h - a) res = (res + A(i) * B(i)) % MOD;
      return res;
    }
};

