{
    int64_t rows, cols;
    cin >> rows >> cols;

    int64_t x, y;
    cin >> x >> y;

    int64_t total = 0;
    for (int64_t i = y + 1; i <= cols; i += 1) {
        int64_t ways = Ways(1, 1, rows - x, i);
        ways = (ways * Ways(rows - x + 1, i, rows, cols)) % kMod;
        total = (total + ways) % kMod;
    }

    cout << total << "\n";
    return 0;
}

