	for (int i = 2; i < MAX; i++) {
		fac[i] = fac[i - 1] * i % mod;
		inv[i] = mod - inv[mod%i] * (mod / i) % mod;
		finv[i] = finv[i - 1] * inv[i] % mod;
	}
}

long long COM(int n, int k) {
	if (n < k) return 0;
	if (n < 0 || k < 0) return 0;
	return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
}

int main() {
	COMinit();
	int h, w, a, b;
	cin >> h >> w >> a >> b;
	ll res = 0;
	REP(i, h - a) {
		res += COM(b - 1 + i, b - 1)*COM(w - b - 1 + h - 1 - i, w - b - 1);
		res %= mod;
	}
	cout << res << endl;

	return 0;
}

