void preprocess() {
  fac[0] = 1;
  for (int i = 1 ; i < MAXNUM ; i++) {
    fac[i] = (fac[i-1] * i) % MOD;
  }
}


ll factorial(int x) {
  return fac[x];
}


ll getPow(ll b, ll e) {
  //cerr << "B = " << b << ", E = " << e << "\n";
  if (e == 0) return 1;
  if (e == 1) return b;
  if (e % 2 == 0) {
    ll tmp = getPow(b, e / 2);
//  cerr << " Ret B = " << b << ", E = " << e << "\n";
    return (tmp * tmp) % MOD;
  } else {
//  cerr << " Ret B = " << b << ", E = " << e << "\n";
    return (b * getPow(b, e - 1)) % MOD;
  }
}


ll getInverse(int x) {
  if (x == 1) {
    return 1;
  }
  return getPow(x, MOD - 2);
}


ll NCR(int n, int k) {
  ll num = factorial(n);
  ll den = (factorial(k) * factorial(n-k)) % MOD;
  //cerr << "LUL\n";
  ll ret =  (num * getInverse(den)) % MOD;
  //cerr << "RET = " << ret << "\n";
  return ret;
}


ll getWays(int fr, int fc, int tr, int tc) {
  int dr = tr - fr;
  int dc = tc - fc;
  //cerr << "DR = " << dr << ", DC = " << dc << "\n";
  return NCR(dr + dc, dr);
}


