  for (int r = 0 ; r < H-A ; r++) {
    //cerr << "R = " << r << "\n";
    ans = (ans + getWays(0, 0, r, B-1) * getWays(r, B, H-1, W-1)) % MOD;
  }
  cout << ans;
}






