ll modpow(ll a, ll b)
{
	if(b < 0) b += (MOD - 1);
	a %= MOD;
	ll r = 1;
	while(b)
	{
		if(b % 2)
		{
			r = (r*a)%MOD;
		}
		a = (a*a)%MOD;
		b /= 2;
	}
	if(r < 0) r += MOD;
	return r;
}

ll inv(ll x)
{
	return modpow(x, MOD - 2);
}

ll choose(ll n, ll r)
{
	if(r == 0)
	{
		return 1;
	}
	if(n == r)
	{
		return 1;
	}
	ll denom = 1;
	for (ll i = 2; i <= r; i++)
	{
		denom = (denom * i) % MOD;
	}
	ll res = 1;
	for (ll i = n; i > n - r; i--) 
	{
		res = (res * i) % MOD;
	}
	res = (res * modpow(denom, MOD - 2)) % MOD;
	if(res < 0) res += MOD;
	return res;
}

