template<ll mod> struct GF {
	ll v;
	GF(ll v = 0) : v((v % mod + mod) % mod) {}
	GF operator+(GF x) const { return v + x.v; }
	GF operator-(GF x) const { return v - x.v; }
	GF operator*(GF x) const { return v * x.v; }
	GF operator/(GF x) const { return x.inverse() * v; }
	GF operator+=(GF x) { return (*this) = (*this) + x; }
	GF operator*=(GF x) { return (*this) = (*this) * x; }
	GF operator-=(GF x) { return (*this) = (*this) - x; }
	GF operator/=(GF x) { return (*this) = (*this) / x; }
	GF inverse() const { // http://topcoder.g.hatena.ne.jp/iwiwi/20130105/1357363348
		ll a = v, b = mod, x = 1, y = 0;
		while (b) {
			ll t = a / b;
			swap(a -= t * b, b);
			swap(x -= t * y, y);
		}
		return x;
	}
	GF pow(ll n) const {
		ll x = v, r = 1;
		for (; n > 0; n >>= 1) {
			if (n & 1) (r *= x) %= mod;
			(x *= x) %= mod;
		}
		return r;
	}

	static vector<GF> fact;
	static void fact_init(ll n) {
		fact.resize(n + 1); fact[0] = 1;
		REP(i, n) fact[i + 1] = fact[i] * (i + 1);
	}

	static GF nCr(ll n, ll r) { return fact[n] / fact[r] / fact[n - r]; }
	static GF nPr(ll n, ll r) { return fact[n] / fact[n - r]; }
};
template<ll mod> vector<GF<mod>> GF<mod>::fact;

