const int FACT_MAX_N = 1000000;
int fact[FACT_MAX_N];
void FactrialInitialize(ll n, ll mod) {
	fact[0] = 1;
	FORLL(i, 1, n) {
		fact[i] = i * fact[i - 1] % mod;
	}
}
ll Factrial(ll n, ll mod) {
	if (fact[0] == 0) FactrialInitialize(FACT_MAX_N, mod);
	if (fact[n] != 0) return fact[n];
	if (n == 0) return fact[n] = 1;
	return fact[n] = Factrial(n - 1, mod) * n % mod;
}

ll powMod(ll n, ll p, ll mod) {
	if (n == 0) return 0;
	if (p <= 0 || n == 1) return 1;
	if (p % 2 == 0) {
		ll t = powMod(n, p / 2, mod);
		return t*t % mod;
	}
	return n*powMod(n, p - 1, mod) % mod;
}

ll Permutation(ll n, ll r, ll mod) {
	if (n < r) return 0;
	if (n == r) return Factrial(n, mod);
	ll ans = 1;
	ans *= Factrial(n, mod); ans %= mod;
	ans *= powMod(Factrial(n - r, mod), mod - 2, mod); ans %= mod;
	return ans;
}

/*fact準備O(n), クエリO(log(mod))*/
ll Combination(ll n, ll r, ll mod) {
	if (r == 0) return 1;
	if (n < r) return 0;
	ll ans = 1;
	ans *= Factrial(n, mod); ans %= mod;
	ans *= powMod(Factrial(n - r, mod), mod - 2, mod); ans %= mod;
	ans *= powMod(Factrial(r, mod), mod - 2, mod); ans %= mod;
	return ans;
}
