    ll all = ModCombination((H - 1) + (W - 1), (H - 1), kMOD);
    for (int w = 0; w < B; w++) {
        ll forbidden = ModCombination((H - A - 1) + w, (H - A - 1), kMOD);
        forbidden *= ModCombination((A - 1) + (W - w) - 1, (A - 1), kMOD);
        forbidden %= kMOD;
