    a = a + b;
    if (a > MOD)
        a -= MOD;
    return a;
}

long long fac[N], rfac[N], inv[N];

void calc(int n) {
    inv[1] = 1;
    for (int i = 2; i <= n; i++) {
        inv[i] = (MOD - (MOD / i) * inv[MOD % i] % MOD) % MOD;
    }
    fac[0] = rfac[0] = 1;
    for (int i = 1; i <= n; i++) {
        fac[i] = mul(fac[i - 1], i);
        rfac[i] = mul(rfac[i - 1], inv[i]);
    }
}

long long comb(int k, int n) {
    return mul(fac[n], mul(rfac[k], rfac[n - k]));
}

