	//1行目からH-A行目までについてi行目の移動回数は
	//右への移動回数は(B-1)回なので 場合の数は(B-1)+(i-1)_C_B-1;
	for(int i=1;i<=H-A;i++){
		ll t = COM(B-1+(i-1),B-1);
		//またi行目について右下までいく場合の数は
		//下にH-i-1回移動して、右にW-B-1回移動するので
		ans += t*COM( (H-i) + W-B-1,H-i);
		ans %= MOD;
	}
	cout << ans << endl;
}

