const size_t MAX_N = (size_t)1e5 + 5;

ll inv[MAX_N << 1], finv[MAX_N << 1], fperm[MAX_N << 1];

void process() {
    for (int i = 0; i < 2; i++) inv[i] = finv[i] = fperm[i] = 1;
    for (int i = 2; i < (MAX_N << 1); i++) {
        inv[i] = (-(MOD / i) * inv[MOD % i] + MOD) % MOD;
        finv[i] = (finv[i - 1] * inv[i]) % MOD;
        fperm[i] = (fperm[i - 1] * i) % MOD;
    }
}

auto C = [](int m, int n) -> ll {
    return fperm[m] * (finv[n] * finv[m - n] % MOD) % MOD;
};

