llong mpow(llong base, llong exp) {
    llong ans = 1;
    for (; exp > 0; exp >>= 1) {
        if (exp & 1) (ans *= base) %= rem;
        (base *= base) %= rem;
    }
    return ans;
}

llong fac[maxn], rfac[maxn];

llong choose(llong n, llong k) {
    return fac[n] * rfac[k] % rem * rfac[n - k] % rem;
}

llong walk_way(llong u, llong v) {
    deb(u, v);
    --u; --v;
    return choose(u + v, u);
}

int main(void) {
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
