    fac[0] = rfac[0] = 1;
    for (int i = 1, mx = 2 * max(h, w); i <= mx; ++i) {
        fac[i] = i * fac[i - 1] % rem;
        rfac[i] = mpow(fac[i], rem - 2);
    }

    llong ans = 0;
    int fr = h - a;
    for (int c = b + 1; c <= w; ++c) {
        int fc = w - c + 1;
        (ans += walk_way(fr, c) * walk_way(a, fc)) %= rem;
    }
    cout << ans;

