long long inverse_md(long long num)
{
    long long val=1;
    int nw=0,po=1;
    base[0]=1;
    cnt[0]=0;
    base[1]=num;
    cnt[1]=1;
    while(nw+cnt[po]<=MOD-2)
    {
        val*=base[po];
        val%=MOD;
        nw+=cnt[po];
        base[po+1]=base[po]*base[po];
        base[po+1]%=MOD;
        cnt[po+1]=cnt[po]*2;
        po++;
    }
    for(int i=po;i>=0;i--)
    {
        if(nw+cnt[i]<=MOD-2)
        {
            val*=base[i];
            val%=MOD;
            nw+=cnt[i];
        }
    }
    //printf("%lld\n",(num*val)%MOD);
    return int(val);
}

