Mod operator*(Mod a, Mod b) { return a *= b; }
Mod operator^(Mod a, ll n) {
	if (n == 0) return Mod(1);
	Mod res = (a * a) ^ (n / 2);
	if (n % 2) res = res * a;
	return res;
}

