}

long long mod_pow(long long a, long long b){
    long long res = 1;
    a %= mod;
    while(b > 0){
        if(b%2 == 0){
            a = (a * a) % mod;
            b /= 2;
        }else{
            res = (res * a) % mod;
            b--;
        }
    }
    return res;
}

long long mod_comb(long long a, long long b){
    if(b < 0 || a < b)return 0;
    long long c = (mod_fact(a) * mod_pow(mod_fact(a-b), mod-2)) % mod;
    return (c * mod_pow(mod_fact(b), mod-2)) % mod;
}

