LL modpow(LL x, LL b){
	LL res = 1;
	while(b){
		if(b&1)res = res * x % MOD;
		x = x * x % MOD;
		b>>=1;
	}
	return res;
}

LL modinv(LL x){
	return modpow(x, MOD-2);
}

LL factorial(LL x){
	static vector<LL> memo((int)2e5, 0);
	memo[1]=1;
	if(x<=1)return 1;
	if(memo[x]>=1)return memo[x];
	int i;
	for(i=memo.size()-1;!memo[i];--i);
	LL res = memo[i];
	for(i=i+1;i<=x;++i){
		res *= i;
		res %= MOD;
		memo[i] = res;
	}
	return memo[x];
}


LL C(LL a, LL b){
	return factorial(a) * modinv(factorial(b) * factorial(a-b) % MOD) % MOD;
}

LL H(LL a, LL b){
	return C(a+b, b);
}

