ll doubling(ll n) {
    ll ret = 1;
    ll a = n;
    bitset<32> bs(MOD - 2);
    for (ll i = 0; i < bs.size(); i++) {
        if (bs[i]) {
            ret *= a;
            ret %= MOD;
        }

        a *= a;
        a %= MOD;
    }

    return ret;
}

ll invert(ll n) {
