    for (int i = 1; i < N; i++) {
        fact[i] = mul(fact[i - 1], i);
    }
    rfact[N - 1] = pw(fact[N - 1], mod - 2);
    for (int i = N - 2; i >= 0; i--) {
        rfact[i] = mul(rfact[i + 1], i + 1);
    }
