int egcd(int a, int b, int &x, int &y)
{
	int xx = y = 0;
	int yy = x = 1;
	while (b)
	{
		int q = a/b;
		int t = b; b = a%b; a = t;
		t = xx; xx = x - q*xx; x = t;
		t = yy; yy = y - q*yy; y = t;
	}
	return a;
}

ll inverse(ll a)
{
	a = a % MOD;
	int x, y;
	egcd(a, MOD, x, y);
	return (x % MOD + MOD) % MOD;
}

