		{
			ll sta = h - 1 + (b - a), stb = w - 1 - (b - a);
			Mod ta = comb(sta, b-a+i), tb = comb(stb, i);
			Mod tmp = ta*tb;
			sum -= tmp;
		}
	}
	else
	{
		REP(i, b)
		{
			ll sta = h - (a-b) - 1, stb = h + w - 2 - sta;
