	for_(i,2,S) fact[i] = (fact[i-1] * i) % MOD;

	vector< lint > inv(S, 0);
	for_(i,1,S) inv[i] = power(fact[i], MOD-2);

	auto nCk = [&](int n, int k) {
		if (k == 0) return 1LL;
		lint res = fact[n];
		modMul(res, inv[n-k], MOD);
		modMul(res, inv[k], MOD);
		return res;
	};

	lint ans = 0;
	for_(y,0,H-A) {
		lint add = nCk(B-1+y, y);
		modMul(add, nCk(H-1+W-B-1-y, W-B-1), MOD);
		modAdd(ans, add, MOD);
	}
	cout << ans << endl;
}

