  combination_mod c(mod);

  long long ans = c.comb( h+w-2, h-1 );

  for(int k=h-a; k<h; k++){
    ans = (ans - c.comb( k+b-1, k ) * c.comb(h-1-k + w-1-b, w-1-b) % mod + mod) % mod ;
  }

  println(ans);

  return 0;
}

