//mintの階乗計算
//O(x)程度の時間がかかります
//Xは降順推奨
mint fact(mint x)
{
	static std::vector<mint> facts({ 1,1 });//[i] == !i(iの階乗) 便宜上0の階乗は1

	if ((size_t)(x) < facts.size()) {
		return facts[(size_t)(x)];
	}
	facts.reserve((size_t)(x)+1);
	mint res(facts.back());
	for (size_t i = facts.size(); i <= (size_t)x; ++i)
	{
		res *= i;
		facts.push_back(res);
	}
	return res;
}

//mintの階乗計算のリスト
//factsに0～xまでの階乗数の列挙をします
//O(x)程度の時間がかかります
inline void fact_set(mint x = mint(-1))
{
	fact(x);
}
//nのうちr個を選ぶ通り数
inline mint combination(mint n, mint r)
{
	//return facts[(size_t)(n)] * ~facts[(size_t)(n - r)] * ~facts[(size_t)r];
	return fact(n) * ~fact(n - r) * ~fact(r);
}

#include <iostream>

int main()
{
	mint h, w, a, b;
