typedef long long LL;

LL pow_mod(LL b, LL p, LL k) {
	LL ret = 1;
	for (; p; p >>= 1) {
		if (p & 1) ret = ret * b % k;
		b = b * b % k;
	} return ret; 
}

const int maxn = (int)(2e5) + 5;
const int mo = (int)(1e9) + 7;
LL fac[maxn], ivf[maxn];

inline LL C(int n, int m) {
	if (m < 0 || n - m < 0) return 0;
	return (fac[n] * ivf[m] % mo) * ivf[n - m] % mo;
}

int main() {
	int h, w, a, b; LL ret = 0;
	scanf("%d%d%d%d", &h, &w, &a, &b);
	int mx = 2 * max(h, w); fac[0] = ivf[0] = 1;
	for (int i = 1; i <= mx; ++i) fac[i] = fac[i - 1] * i % mo;
	ivf[mx] = pow_mod(fac[mx], mo - 2, mo);
	for (int i = mx - 1; i >= 1; --i) ivf[i] = ivf[i + 1] * (i + 1) % mo;
	for (int i = b + 1; i <= w; ++i) (ret += C(h - a - 1 + i - 1, i - 1) * C(a - 1 + w - i, a - 1)) %= mo; 
