struct Fact_combination {
private:
	vector<ll>FACT;
	vector<ll>IFACT;
	ll N;
public:
	ll extgcd(ll a, ll b, ll &x, ll &y) {
		ll g = a;
		x = 1;
		y = 0;
		if (b != 0) g = extgcd(b, a % b, y, x), y -= (a / b) * x;
		return g;
	}
	ll invMod(ll a, ll m) {
		ll x, y;
		if (extgcd(a, m, x, y) == 1) return (x + m) % m;
		else                         return 0;
	}
	ll mod_pow(ll x, ll n) {
		ll res = 1;
		while (n > 0) {
			if (n & 1) res = res * x%MOD;
			x = x * x%MOD;
			n >>= 1;
		}
		return res;
	}
	void inverse(ll n) {
		N = n;
		FACT.resize(N + 1);
		IFACT.resize(N + 1);
		FACT[0] = 1;
		IFACT[0] = 1;
		for (int i = 1;i <= N;i++) {
			FACT[i] = FACT[i - 1] * i % MOD;
			IFACT[i] = invMod(FACT[i], MOD);
		}
	}
	ll combi(ll n, ll r) {
		if (n < 0 || r < 0 || r > n)return 0;
		if (r > n / 2)r = n - r;
		return FACT[n] * IFACT[n - r] % MOD*IFACT[r] % MOD;
	}
};

ll h, w, a, b, ans;

int main() {
	cin >> h >> w >> a >> b;
	Fact_combination fa;
	fa.inverse(h + w + 1);
	for (int i = 0;i < h - a;i++) {
		ans += fa.combi(i + b - 1, i)*fa.combi(h - i + w - b - 2, h - i - 1);
		ans %= MOD;
	}
	cout << ans << endl;
	return 0;
}

