int H, W, A, B, S;
ll M = 1000000007;
ll FACT[200001], FACT_INV[200001];

ll mod_pow(ll a,ll n){
    ll x = 1;

    while(n>0){
        if(n&1) x = x * a % M;

        a = a * a % M;
        n >>= 1;
    }
    return x;
}

ll combination(int n, int r){
    if(n==0 && r==0) return 1;
    else if(n<r || n<0) return 0;

    ll res = FACT[n] * FACT_INV[r] % M;
    return res * FACT_INV[n-r] % M;
}

int main(){
    cin>> H >> W >> A >> B;
    S = H + W - 2;

    FACT[0] = FACT_INV[0] = 1;
    for(int i=1;i<S+1;i++) FACT[i] = FACT[i-1] * i % M;

    FACT_INV[S] = mod_pow(FACT[S], M-2);
    for(int i=S-1;0<=i;i--) FACT_INV[i] = FACT_INV[i+1] * (i+1) % M;

    ll com = combination(S, H-1), bef = 0;
    for(int i=0;i<B;i++){
        ll c1 = combination(H-A+i, H-A), c2 = combination(S-H+A-i, A-1);
        ll tmp = (c1-bef) * c2 % M;
        bef += c1 - bef;
        com -= tmp;
        if(com<0) com += M;
    }

    cout << com % M << endl;

    return 0;
}

