//modの整数クラス
class mint
{
public:
	static void set_mod(long long m_)
	{
		//無効な値は無視
		if (m_ < 2)return;
		//modの値を更新
		mod = m_;
		//オイラー関数Φ(mod)を計算する
		e_phi = m_;
		for (int i = 2; i * i <= m_; ++i)
		{
			if (m_ % i == 0)
			{
				e_phi = e_phi / i * (i - 1);
				for (; m_ % i == 0; m_ /= i);
			}
		}
		if (m_ != 1)e_phi = e_phi / m_ * (m_ - 1);
	}
	mint operator+(const mint &other)const
	{
		return mint(imod(value + other.value, mod));
	}
	mint operator-(const mint &other)const
	{
		return mint(imod(value - other.value, mod));
	}
	mint operator*(const mint &other)const
	{
		return mint(imod(value * other.value, mod));
	}
	mint operator+=(const mint &other)
	{
		value = imod(value + other.value, mod);
		return mint(value);
	}
	mint operator-=(const mint &other)
	{
		value = imod(value - other.value, mod);
		return mint(value);
	}
	mint operator*=(const mint &other)
	{
		value = imod(value * other.value, mod);
		return mint(value);
	}
	mint operator+()const
	{
		return *this;
	}
	mint operator-()const
	{
		return mint(-value);
	}
	mint& operator++()
	{
		*this += 1;
		return *this;
	}
	mint operator++(int)
	{
		auto tmp = *this;
		*this += 1;
		return tmp;
	}
	mint& operator--()
	{
		*this -= 1;
		return *this;
	}
	mint operator--(int)
	{
		auto tmp = *this;
		*this -= 1;
		return tmp;
	}
	mint operator~()const
	{
		return pow(value, e_phi - 1);
	}
	mint& operator=(const mint &other)
	{
		value = other.value;
		return *this;
	}
	operator long long()const
	{
		return value;
	}
	static long long getmod()
	{
		return mod;
	}
	mint(long long a_) :value(imod(a_, mod)) {}
	mint() :value(0) {}
private:
	static long long mod;
	static long long e_phi;
	long long value;
};

