ll modpow(ll a,ll b){
	ll res=1;
	while(b){
		if(b&1) res=(res*a)%MOD;
		a=(a*a)%MOD;
		b>>=1;
	}
	return res;
}
ll f[MAXN];
ll invf[MAXN];

ll ncr(ll n,ll r){
	if(r==0 || n==r) return 1;
	return (((f[n]*invf[n-r])%MOD)*invf[r])%MOD;
}


