    if (datai[a]) return datai[a];
    return datai[a] = mod_inv_fact(a + 1) * (a + 1) % MOD;
}

ll mod_comb_fast(ll n, ll r) {
    if (r < 0 || n < r) return 0LL;
    if (r == 0 || r == n) return 1LL;
    return mod_fact(n) * mod_inv_fact(n - r) % MOD * mod_inv_fact(r) % MOD;
}

