ll power(ll x, ll n, ll mod = numeric_limits<ll>::max()) {
  assert(n >= 0);
  if (n == 0) return 1;
  return power(x * x % mod, n / 2, mod) * (n % 2 ? x : 1) % mod;
}
ll inv(ll x, ll p = mod) {
  assert((x %= p) != 0);
  return power(x, p - 2, p);
}
ll comb(ll n, ll r, ll mod = 0) {
  assert(n >= 0 and r >= 0);
  if (r > n) return 0;
  r = min(r, n - r);
  ll res = 1;
  if (mod) for (ll i = 0; i < r; i++) res = res * (n - i) % mod * inv(i + 1) % mod;
  else for (ll i = 0; i < r; i++) res = res * (n - i) / (i + 1);
  return res;
}
ll f(ll x, ll y) {
  return comb(x + y - 2, x - 1, mod);
}
