        if(x <= 1) break;
        if(y >= W) break;
        p.pb(mp(x-1, y+1));
    }

    ll ans = 0;
    rep(i,p.size()){
        ll px, py;
        px = p[i].first;
        py = p[i].second;

        ll ret, x, y;
        ret = 0;
        x = px - 1;
        y = py - 1;
        ret += C.nCr(x+y, x);

        x = H - px;
        y = W - py;
        ret *= C.nCr(x+y, x);
        ret %= inf;
        ans += ret;
        ans %= inf;
    }
    cout << ans << endl;
    //cout << fixed << setprecision(16) << ans << endl;
    return 0;
}

