lli ext_gcd(lli a, lli b, lli &x, lli &y)
{
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    lli d = ext_gcd(b, a % b, y, x);
    y -= a / b * x;
    return d;
}

lli mod_inverse(lli a, lli m)
{
  lli x, y;
  ext_gcd(a, m, x, y);
  return (m + x % m) % m;
}

