  while (y >= 0 && x < W) {
    ll fr = getC(y + x, y);
    ll to = getC(H - y - 1 + W - x - 1, H - y - 1);
    (ans += fr * to % mod) %= mod;
    y--; x++;
  }

  _p("%lld\n", ans);
}
