void make_perms()
{
    perms[0] = 1LL;
    perms_inv[0] = 1LL;

    srep (i, 1LL, 200005) {
        perms[i] = perms[i-1] * i;
        perms[i] %= mod;
        perms_inv[i] = mod_inv(perms[i], mod);
    }

    rep (i, 8) {
        debug_printf("perms[%lld]=%lld inv=%lld\n", i, perms[i], perms_inv[i]);
    }
}

ll solve(ll h1, ll w1, ll h2, ll w2)
{
    debug_printf("h1=%lld w1=%lld h2=%lld w2=%lld\n",
                 h1, w1, h2, w2);

    ll ret1 = 1LL;
    ret1 *= perms[h1+w1-2];
    ret1 %= mod;
    ret1 *= perms_inv[h1-1];
    ret1 %= mod;
    ret1 *= perms_inv[w1-1];
    ret1 %= mod;

    ll ret2 = 1LL;
    ret2 *= perms[h2+w2-2];
    ret2 %= mod;
    ret2 *= perms_inv[h2-1];
    ret2 %= mod;
    ret2 *= perms_inv[w2-1];
    ret2 %= mod;

    ll ret = ret1 * ret2;
    ret %= mod;

    debug_printf("ret1=%lld ret2=%lld ret=%lld\n", ret1, ret2, ret);

    return ret;
}

