typedef math::modulo_number<1000000007> number_t;
number_t helper(number_t k,number_t n)
{
	number_t ret = 1;
	for (int i{};i < n.get();++i)
	{
		ret *= (k + i);
	}
	return ret / n;
}
std::vector<number_t> check(std::vector<number_t>const& data, std::size_t H)
{
	std::vector<number_t> ret;
	int W = data.size();
	for (int i{};i < W;++i)
	{
		number_t num;
		for (int index = 1;index <= i;++index)
		{
			num += data[i - index] * helper(H - 1, index);
		}
	}
	return ret;
}

void Main(std::integral_constant<int, 2>)
{
	int H, W, A, B;
	std::cin >> H >> W >> A >> B;
	std::vector<math::modulo_number<1000000007>> data(W, number_t(1));
	auto vec = check(data, H - A);
	auto ite = std::next(vec.begin(), B);
	vec.erase(vec.begin(), ite);
	auto ret = check(vec, A + 1);
	std::cout << ret.back().get() << std::endl;
}

