using namespace std;

typedef long long ll;

const ll MOD = 1000000007;

/* x^nを高速に求める */
ll mod_pow(ll x, ll n) {
	ll res = 1;
	while (n > 0) {
		if (n & 1) res = res*x%MOD;  // 最下位ビットが立ってる時にx^(2^i)を掛ける
		x = x*x%MOD;              // xを順次二乗していく
		n >>= 1;    // 右ビットシフト
	}
	return res;
}

// (a+b)!/a!*b! を求める
ll mod_path(ll a, ll b) {
	ll x=1, y=1;
	for (ll w = a; w > 0; w--) {
		x *= (w+b);
		x %= MOD;
	}
	for (ll w = a; w > 0; w--) {
		y *= w;
		y %= MOD;
	}

	return x * mod_pow(y,(ll)1000000005) % MOD;
}

int main() {
	ll H, W, A, B;
	cin >> H >> W >> A >> B;

	W--; H--;
	ll ap = mod_path(H,W);
	//cout << mod_path(W,H) << endl;

	vector<ll> stp(B), tgp(B); // s->t, t->g
	stp[B-1] = mod_path(B-1, H-A);
	//cout << stp[B-1] << endl;
	for (ll i = B - 2, j=0; i >= 0; i--,j++) {
		stp[i] = (i + 1)*stp[i+1]*mod_pow((B - 1 + H - A - j), (ll)1000000005)%MOD;
		stp[i] %= MOD;
		//cout << stp[i] << endl;
	}
	tgp[0] = mod_path(W,A-1);
	//cout << tgp[0] << endl;
	for (ll i = 1; i < B; i++) {
		tgp[i] = (W-(i-1))*tgp[i-1]*mod_pow((W-(i-1)+A-1), (ll)1000000005)%MOD;
		tgp[i] %= MOD;
		//cout << tgp[i] << endl;
	}
	ll sum=0;
	for (ll i = 0; i < B; i++) {
		sum += stp[i]*tgp[i];
		sum %= MOD;
	}
	sum %= MOD;
	//cout << ap <<" "<< sum << endl;
	cout << (ap-sum)%MOD << endl;

}

