ll power_mod(ll n, ll m)
{
    ll base = n;
    ll res = 1;
    while (m > 0)
    {
        if (m & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        m >>= 1;
    }
    return res;
}

ll fact[MAX_HW*10];
void init_fact()
{
    fact[0] = fact[1] = 1;
    rep(i, 2, MAX_HW*10)
        fact[i] = (fact[i - 1] * i) % MOD;
}

ll inv_mod(ll n)
{
    return power_mod(n, MOD - 2);
}

ll comb(int n, int m)
{
    if (n == 0 or m == 0) return 1;
    if (n == m) return 1;
    ll res = 1;
    res = (res * fact[n]) % MOD;
    res = (res * inv_mod(fact[m])) % MOD;
    res = (res * inv_mod(fact[n - m])) % MOD;
    return res;
}

