    ll c = h-a;
    ll ans = 0;
    getFac();
    for (ll i = 1; i<=c; i++) {
        ans += getC(i+b-2, b-1) * getC(h-i+w-b-1, w-b-1) % mod;
        ans %= mod;
    }
    printf("%lld\n", ans);
}

#include "bits/stdc++.h"
using namespace std;
long long mod=1e9+7;

long long modpow(long long a,long long p){
    if(p==0)return 1;
    if(p%2==0){
      long long halfP=p/2;
      long long half=modpow(a,halfP);
      return half*half%mod;
    }else{
      return a*modpow(a,p-1)%mod;
    }
}

long long comb(long long a,long long b){
  if(b>a-b)return comb(a,a-b);
  long long ansMul=1;
  long long ansDiv=1;
  for(int i=0;i<b;i++){
    ansMul*=(a-i);
    ansDiv*=(i+1);
    ansMul%=mod;
    ansDiv%=mod;
  }
  long long ans=ansMul*modpow(ansDiv,mod-2)%mod;
  return ans;
}

int main(){
