  tx[0]=1;
  fx[0]=1;
  for(int i=1;i<h+w+2;i++){
    tx[i]=(i*tx[i-1])%mod;
    fx[i]=modpow(tx[i],mod-2);
  }
  long long ans=0;
  for(int i=0;i+b<=w;i++){
    long long x=(h-a-1)+(b+i);
    long long y=(h-a-1);
    long long l=(a-1)+(w-b-1-i);
    long long r=(w-b-1-i);
    ans+=((((tx[x]*fx[y])%mod)*fx[x-y])%mod)*((((tx[l]*fx[r])%mod)*fx[l-r])%mod)%mod;
    ans%=mod;
  }
  ans%=mod;
  cout<<ans<<endl;
}

