#include <bits/stdc++.h>
using namespace std;
using ll = long long;
int H, W, A, B;
const int K = 1E9 + 7 + 1E-5;
ll pow_mod(ll n, ll k, ll m) {
  assert(k >= 0);
  assert(m > 0);
  ll ret = 1;
  ll base = n % m;
  while (k) {
    if (k & 1) {
      ret = (ret * base) % m;
    }
    base = (base * base) % m;
    k /= 2;
  }
  return ret;
}

ll choose(ll n, ll k) {
  ll ret = 1;
  for(ll i = 1; i <= k; ++i) {
    ret *= n--;
    ret /= i;
  }
  return ret;
}

ll perm(ll n, ll k) {
  ll ret = 1;
  while(k--) {
    ret *= n--;
  }
  return ret;
}

ll perm_mod(ll n, ll k, const ll m) {
  assert(m > 0);
  ll ret = 1;
  while(k--) {
    ret = (ret * ((n--) % m)) % m;
  }
  return ret;
}

ll choose_mod(ll n, ll k) {
  const ll up = perm_mod(n, n, K);
  const ll dm = (perm_mod(k, k, K) * perm_mod(n - k, n - k, K)) % K;

  const ll idm = pow_mod(dm, K - 2, K);

  return (up * idm) % K;
}
int ct(int h, int w) {
  if (h == 0 || w == 0) return 0;
  return choose_mod(h + w - 2, min(h, w) - 1);
}

int main() {
  cin >> H >> W >> A >> B;
  if (A == H || B == W) {
    cout << 0 << endl;
    return 0;
  }
  long long ret = ct(H, W);

  int n1 = H - 1 + B - 1;
  const int k1 = B - 1;
  int n2 = W - 1 - B + 1 - 1;
  const int k2 = W - 1 - B;

  long long d1 = choose_mod(n1, k1);
  long long d2 = choose_mod(n2, k2);

  for (int i = 0; i < A; ++i) {
    ret -= (d1 * d2) % K;
    ret += K;
    ret %= K;
    ll nd1 = (d1 * (n1 - k1)) % K;

    nd1 = (nd1 * pow_mod(n1, K - 2, K)) % K;
    n1--;
    n2++;

    ll nd2 = (d2 * n2) % K;

    nd2 = (nd2 * pow_mod(n2 - k2, K - 2, K)) % K;
    d1 = nd1;
    d2 = nd2;
  }
  cout << ret << endl;
}

