long long const MOD = 1000000007;

// 階乗 (mod とりバージョン)
ll fact_mod(ll n, ll mod) {
    ll f = 1; for(long long i = 2; i <= n; i++) f = f * (i % MOD) % MOD;
    return f;
}

// 繰り返し二乗法 (modの世界での累乗)
// ※modが素数の場合、この関数で(mod - 2)乗したら、mod割り算ができるよ！
// (参考問題: ABC034 C問題など)
ll mod_pow(ll x, ll n, ll mod) {
    ll res = 1;
    while(n > 0) {
        if(n & 1) res = (res * x) % mod; //ビット演算(最下位ビットが1のとき)
        x = (x * x) % mod;
        n >>= 1; //右シフト(n = n >> 1)
    }
    return res;
}

// 組み合わせ nCr を求める (modあり)
ll combination_mod(ll n, ll r, ll mod) {

    if(r > n-r) r = n-r;    
    long long res = ((((fact[n] % mod) * (fact_in[r] % mod)) % mod) * (fact_in[n - r] % mod)) % mod;

    /*
    if(r == 0) return 1;
    ll a = 1;
    for(long long i = 0; i < r; i++) a = a * ((n-i) % mod) % mod;
    ll b = mod_pow(fact_mod(r, mod), mod-2, mod);
    return (a % mod) * (b % mod) % mod;
    */

    return res;
}

int main(){


    fact[0] = 1;
    for(long long i = 1; i < 1000000; i++){
        fact[i] = ((fact[i - 1] % MOD) * (i % MOD)) % MOD;
    }


    for(ll i = 0; i < 1000000; i++){
        fact_in[i] = mod_pow(fact[i], MOD - 2, MOD) % MOD;
    }

    long long ans = 0;
    long long h, w, a, b; cin >> h >> w >> a >> b;
    a = h - a;
    for(ll j = b + 1; j <= w; j++){
        ans += (combination_mod(a + j - 2, j - 1, MOD) % MOD) * (combination_mod(w - j + h - a - 1, w - j, MOD) % MOD);
        ans %= MOD;
        //cout << a + j - 2 << " " << j - 1 << "   " << w - j + h - a - 1 << " " << w - j << endl;
        //cout << j << " " << ans << endl;
    }

    cout << ans << endl;
}

