	ios::sync_with_stdio(false), cin.tie(0), cout.tie(0);
	pre_process();
	cin >> n >> m >> A >> B;
	A = n - A;
	B = m - B;
	int x = A, y = m - B + 1;
	while (x && y <= m) {
		ans = _sum(ans, _mul(_choose(x - 1, x + y - 2), _choose(n - x, n - x + m - y)));
		x--;
		y++;
	}

	cout << ans << "\n";
	return 0;
}

