// x^n (mod を法として)
ll mod_pow(ll x,ll n,ll mod){
    ll r=1;
    while(n>0){
        if(n&1){
            r=r*x%mod;
        }
        x=x*x%mod;
        n>>=1;
    }
    return r;
}



ll mod_inv_prime(ll n,ll mod){
    return mod_pow(n,mod-2,mod)%mod;
}


ll mod_comb(ll n,ll k,ll mod){
    ll r=1;
    for(ll i=1;i<=k;i++){
        r=r*(n-k+i)%mod;
        r=r*mod_inv_prime(i,mod)%mod;
    }
    return r;
}


