    Combination com(200000);
    const int MOD = 1000000007;
    ll res = 0;
    for(int i=B;i<=W-1;i++){
        res+=com.comb(H-A-1+i,i)*com.comb(A-1+(W-i-1),A-1)%MOD;
        res%=MOD;
    }
    cout << res << endl;
    return 0;
}

