using namespace std;

ll pow_mod(ll a, ll b)
{
	ll ret = 1;
	while (b)
	{
		if (b & 1) ret = ret * a%mod;
		b >>= 1;
		a = a * a%mod;
	}
	return ret;
}

void Init()
{
	A[0] = 1;
	for (int i = 1; i <= maxn; i++)
		A[i] = (A[i - 1] * i) % mod;
	for (int i = maxn; i >= 0; i--)
		B[i] = pow_mod(A[i], mod - 2);
}

ll C(ll n, ll m) {
	if (n < m)
		return 0;
	return (A[n] * B[m] % mod)*B[n - m] % mod;
}

ll count_ways(ll a, ll b, ll c, ll d) {
	ll tot = (c - a) + (d - b);
	ll down = (c - a);
	ll ret = C(tot, down);
	return ret;
}

