  return ((fact[N] * rfact[K]) % MOD * rfact[N - K]) % MOD;
}

int main() {
  init();
  cin >> H >> W >> A >> B;
  long res = comb(H + W - 2, H - 1);
  for(int i = 0; i < B; i++) {
    res -= (comb(i + (H - A - 1), i) * comb(A - 1 + (W - 1 - i), A - 1)) % MOD;
    if(res < 0) res += MOD;
  }
  cout << res << endl;
}

