LL modPow(LL a, LL b)
{
    LL ret = 1;
    while(b)
    {
        if(b&1) ret = ret*a%mod;
        a = a*a%mod;
        b >>= 1;
    }
    return ret;
}

void init()
{
    fac[0] = 1;
    inv[0] = 1;
    for(LL i = 1; i <= H+W; ++i)
