set<int> factorize(long long n)
{
    set<int> factors;
    int count = 0;

    while (!(n % 2)) {
        n >>= 1;
        count++;
    }

    if(count)factors.insert(2);

    for (long long i = 3; i <= 200; i += 2) {
        count = 0;
        while (n % i == 0) {
            count++;
            n = n / i;
        }
        if (count)
            factors.insert(i);
    }

    if (n > 2)
        factors.insert(n);
    return factors;
}

