ll fact[200010];

void init(void) {
  fact[0] = fact[1] = 1;
  for (int i = 2; i <= 200000; i++) {
    fact[i] = fact[i - 1] * i % mod;
  }
}

ll mod_pow(ll x, ll n) {
  if (n == 1) return x;
  ll res = mod_pow(x * x % mod, n / 2);
  if (n & 1) res = res * x % mod;
  return res;
}

ll nCk(int n, int k) {
  if (n < 0 || k < 0 || n < k) return 0;
  if (k == 0 || k == n) return 1;
  ll res = fact[n];
  res = res * mod_pow(fact[k], mod - 2) % mod;
  res = res * mod_pow(fact[n - k], mod - 2) % mod;
  return res;
}

int main(void) {
  init();

  int h, w, a, b;
  cin >> h >> w >> a >> b;

  ll ans = 0;
  for (int i = 0; i < w - b; i++) {
    ans = (ans + nCk(h - a + b - 1, b + i) * nCk(w + a - b - 1, a + i) % mod) % mod;
  }
  cout << ans << endl;

  return 0;
}

