long long KissMe(long long xx, long long yy)
{
	if (yy == 0LL)
	{
		return 1LL;
	}
	long long Res = KissMe((xx*xx) % (long long)MODULO, yy >> 1);
	if (yy % 2LL == 1LL)
	{
		Res *= xx;
		Res %= (long long)MODULO;
	}
	return Res;
}

