long long calcComb(ll a, ll b) {
	if (b > a - b) return calcComb(a, a - b);


	ll ansMul = 1;
	ll ansDiv = 1;
	for (int i = 0; i < b; i++)
	{
		ansMul *= (a - i);
		ansDiv *= (i + 1);
		ansMul %= MOD;
		ansDiv %= MOD;
	}
	//ansMul / ansDivをやりたい
	//ansDivの逆元を使って求めよう！

	ll ans = ansMul * pow_mod(ansDiv,MOD - 2,MOD);
	return ans;
}

