ll fast_exp(ll x, ll y){
	ll ans = 1;
	ll tmp = x;
	while(y){
		if(y%2 == 1) ans = m(ans, tmp);
		tmp = m(tmp, tmp);
		y /= 2;
	}
	return ans;
}

ll d(ll x, ll y){
	return m(x, fast_exp(y, MOD-2));
}

ll sm(ll x, ll y){
	return (x + y) % MOD;
}

ll sb(ll x, ll y){
	return (MOD + (x%MOD) - (y%MOD)) % MOD;
}

ll ncr(ll x, ll y){
	return d(fat[x+y], m(fat[x], fat[y]));
}

