	if ((w - b) < (h - a)) {
		int tmp = h;
		h = w;
		w = tmp;
		tmp = a;
		a = b;
		b = tmp;
	}
	//Σ_[i=0,...,(h-a-1)] (C[b+h-a-1,i]*C[w-b+a-1,(w-b)-(h-a)+i])
	int maxval = max(b + h - a - 1, w - b + a - 1);
	int minval = min(b + h - a - 1, w - b + a - 1);
	long long factmax = 1;
	long long factmin;
	for (int i = 1; i <= maxval; i++) {
		factmax *= i;
		factmax %= mod;
		if (i == minval) factmin = factmax;
	}
	// factmaxの逆元を計算する
	vector<long long> invfact(maxval+ 1);
	invfact[maxval] = inv(factmax);
	for (int i = maxval ; i > 0; i--) {
		invfact[i-1] = (i*invfact[i]) % mod;
	}
	long long den = 0;
	long long tmp;
	for (int i = 0; i < h - a; i++) {
		tmp = invfact[i];
		tmp *= invfact[b + h - a - 1 - i];
		tmp %= mod;
		tmp *= invfact[(w - b) - (h - a) + i];
		tmp %= mod;
		tmp *= invfact[h - i - 1];
		tmp %= mod;
		den += tmp;
		den %= mod;
	}

	cout << (((factmax*factmin)%mod)*den) % mod << endl;
	return 0;
}

