	LL h, w, a, b; cin >> h >> w >> a >> b;

	LL ans = 0;
	for(LL i = h-a, j = b+1; i > 0 && j <= w; i--, j++)
		ans = (ans+paths(i,j)*paths(h-i+1,w-j+1))%MOD;
