long extgcd(long a,long b,long &x,long &y){
  long d=a;
  if(b!=0){
    d=extgcd(b,a%b,y,x);y-=(a/b)*x;
  }else{
    x=1;y=0;
  }
  return d;
}

long mod_inverse(long a) {
  long x, y;
  extgcd(a, MOD, x, y);
  x %= MOD;
  if(x < 0) x += MOD;
  return x;
}
