  rfact[0] = fact[0] = 1;
  for(int i = 1; i < 220000; i++) {
    fact[i] = (fact[i - 1] * i) % MOD;
    rfact[i] = mod_inverse(fact[i]);
  }
}

long comb(long N, long K) {
  if(K < 0) return 0;
  if(N - K < 0) return 0;
  return ((fact[N] * rfact[K]) % MOD * rfact[N - K]) % MOD;
}

