using namespace std;

#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)

typedef long long ll;

//------------------------------------------------------------------------------
int extgcd(int a, int b, int &x, int &y) {
  int ret = a;
  if (b == 0) {
    x = 1;
    y = 0;
  } else {
    ret = extgcd(b, a % b, y, x);
    y -= (a / b) * x;
  }
  return ret;
}

int mod_inverse(int a, int m) {
  int x, y;
  extgcd(a, m, x, y);
  return (m + x % m) % m;
}

//------------------------------------------------------------------------------
const int N_MAX = 200000;

ll fact[N_MAX + 1];

void init_fact(ll n, ll mod) {
  fact[0] = 1;
  FOR(i, 1, n) fact[i] = fact[i - 1] * i % mod;
}

ll mod_comb(ll n, ll k, ll mod) {
  if (n < 0 || k < 0 || n < k) return 0;
  ll a = fact[n];
  ll b = fact[k] * fact[n - k] % mod;
  return a * mod_inverse(b, mod) % mod;
}

//------------------------------------------------------------------------------
const ll MOD = 1000000007;

int H, W, A, B;

void solve() {
  init_fact(H + W, MOD);
  ll ans = 0;
  REP(i, H - A) {
    ll a = mod_comb(i + B - 1, B - 1, MOD);
    ll b = mod_comb(H - i + W - B - 2, W - B - 1, MOD);
    ans = (ans + (a * b % MOD)) % MOD;
  }
  printf("%lld\n", ans);
}

void input() {
  scanf("%d%d%d%d", &H, &W, &A, &B);
}

int main() {
  input();
  solve();
  return 0;
}

