const int N = 200006;
ll fact[N];
ll inv[N];

void calc()
{
  fact[0] = 1;
  inv[0] = modInverse(fact[0]);
  for (int i = 1; i < N; i++) {
    fact[i] = modMul(fact[i - 1], i);
    inv[i] = modInverse(fact[i]);
  }
}

ll nCr(ll n, ll r)
{
  if (r > n)return 0;
  return modMul(fact[n], modMul(inv[n - r], inv[r]));
}


