template <typename Int, int N>
struct mod_CPH {
    array<Int, N + 1> fc, ifc;

    mod_CPH() {
        fc[0] = 1;
        for (int i = 1; i <= N; i++) fc[i] = mod(fc[i - 1] * i);
        ifc[N] = modpow(fc[N],1e9+5);
        for (int i = N - 1; i >= 0; i--) ifc[i] = mod(ifc[i + 1] * (i + 1));
    }

    Int nPr(Int n, Int r) {
        if (r < 0 || n < r)return 0;
        return mod(fc[n] * ifc[n - r]);
    }

    Int nCr(Int n, Int r) {
        if (n < 0 || r < 0 || n < r) return 0;
        return mod(mod(fc[n] * ifc[r])*ifc[n - r]);
    }

    Int nHr(Int n, Int r) {
        if (n < 0 || r < 0) return 0;
        return r == 0 ? 1 : nCr(n + r - 1, r);
    }
};


mod_CPH<ll,2000000> mc;

