const int N = 2e5 + 10;
const int mod = 1e9 + 7;
typedef long long LL;

LL F[N], R[N];

LL pow_mod(LL x, int p){
	LL s = 1;
	while(p){
		if(p & 1) 	s = s * x % mod;
		x = x * x % mod;
		p >>= 1;
	}
	return s;
}

LL C(int n, int m){
	return F[n] * R[m] % mod * R[n-m] % mod;
}

int main(){
	F[0] = R[0] = 1;
	for(int i=1; i<N; i++){
		F[i] = F[i-1] * i % mod;
		R[i] = pow_mod(F[i], mod-2);
	}
    int h, w, a, b;

    while(~scanf("%d %d %d %d", &h, &w, &a, &b)){
        int c = h - a;
		int d = w - b;
        LL ans = 0;
        for(int i=1; i<=c; i++){
            if(i == c){
				ans = ans + C(a+d-1, a) * C(c-1+b, c-1) % mod;
            } else {
				if(d > 1){
					ans = ans + C(i-1+b, i-1) * C(h-i+d-2, h-i) % mod;
				}
            }
            if(ans >= mod){
				ans %= mod;
            }
        }
        printf("%lld\n", ans);
	}
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 1e9 + 7;     //  必须为质数才管用
const ll MAXN = 1e5 + 3;

ll fac[MAXN];       //  阶乘
ll inv[MAXN];       //  阶乘的逆元

ll QPow(ll x, ll n)
{
    ll ret = 1;
    ll tmp = x % MOD;
    while (n)
    {
        if (n & 1)
        {
            ret = (ret * tmp) % MOD;
        }
        tmp = tmp * tmp % MOD;
        n >>= 1;
    }

    return ret;
}

void Init()
{
    fac[0] = 1;
    for (int i = 1; i < MAXN; i++)
    {
        fac[i] = fac[i - 1] * i % MOD;
    }
    inv[MAXN - 1] = QPow(fac[MAXN - 1], MOD - 2);
    for (int i = MAXN - 2; i >= 0; i--)
    {
        inv[i] = inv[i + 1] * (i + 1) % MOD;
    }
