    long ans = 0;
    for (long i = 0; i < h - a; i++) {
        ans = (ans + (mod_combi(b + i - 1, i) * mod_combi(w - b + h - i - 2, h - i - 1)) % BASE) % BASE;
    }
    cout << ans << endl;
    return 0;
}

