void solve(istream& in, ostream& out) {
  auto n = next<int>(in);
  auto m = next<int>(in);
  auto a = next<int>(in);
  auto b = next<int>(in);

  int N = n + m - 2;
  int K = n - 1;

  md res = C(N, K);
  for (int row = n - a + 1, row2 = a; row <= n; ++row, --row2) {

    N = row + b - 2;
    K = row - 1;

    int N2 = row2 + (m - b) - 2;
    int K2 = row2 - 1;
    res -= C(N, K) * C(N2, K2);

  }

  out << res << "\n";
}

