// returns n = (b**p) mod m
i64 modpow(i64 b, i64 p, i64 m) {
    i64 n=1, a=b%m;
    while (p) {
        if (p & 1)
            n = (n*a) % m;

        a = (a*a) % m;
        p >>= 1;
    }
    return n;
}

// returns a^(-1) mod m
i64 modinv(i64 a, i64 m=mod) {
    return modpow(a, m-2, m) % m;
}

vx modfact_table(int n, int mod=1e9+7) {
    vx table(n+1);
    table[0] = 1;

    int i;
    for (i=1; i<=n; i++)
        table[i] = (table[i-1]*i) % mod;

    return table;
}

vx modfactinv_table(int n, i64 factn=-1, i64 mod=1e9+7) {
    vx table(n+1);
    int i;
    if (factn == -1) {
        factn = 1;
        for (i=1; i<=n; i++)
            factn = (factn*i) % mod;
    }
    table[n] = modinv(factn);
    for (i=n; i--;)
        table[i] = (table[i+1]*(i+1)) % mod;

    return table;
}

