LL F[200005], R[200005];
long long  powmod(long long  x, long long  n, long long  MOD) {
	long long  res = 1;
	while (n > 0) {
		if (n & 1) {
			res = (res*x) % MOD;
		}
		x = (x*x) % MOD;
		n >>= 1;
	}
	return res;
}
void make() {
	F[0] = 1;
	for (int i = 1; i<200005; i++) F[i] = F[i - 1] * i%MOD;
	for (int i = 0; i<200005; i++) R[i] = powmod(F[i], MOD - 2, MOD);
}

LL nCr(int a, int b) {
	return F[a] * R[b] % MOD*R[a - b] % MOD;
}

