long long modpow(long long a, long long b) {
  long long r = 1LL;

  while (b) {
    if (b & 1LL)r *= a;
    if (r >= MOD)r %= MOD;
    a *= a;
    if (a >= MOD)a %= MOD;
    b >>= 1LL;
  }
  return r;
}

ll f(ll a, ll b) {
  if (a == 0)return 1;
  ll ret = 1;
  rep(i, 0, a) {
    ret *= (b + 1) + i;
    ret %= MOD;
  }
  rep(i, 1, a) {
    ret *= modpow(i + 1, MOD - 2);
    ret %= MOD;
  }
  return ret % MOD;
}

ll f2(ll a, ll b) {
  if (dp[a] != -1)return dp[a];
  dp[0] = 1;
  ll ret = 1;
  rep(i, 0, a) {
    ret *= (b + 1) + i;
    ret %= MOD;
    ret *= modpow(i + 1, MOD - 2);
    ret %= MOD;
    dp[i + 1] = ret % MOD;
  }
  return ret;
}

