import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	void solve() {
		int h = ni(), w = ni(), a = ni(), b = ni();
		long res = 0, mod = 1000000007;
		Combination2 c = new Combination2(100100 * 2, mod);
		for (int i = 0; i < h - a; ++i) {
			long x = c.combination(b + i - 1, b - 1);
			long y = c.combination(h - i - 1 + w - b - 1, w - b - 1);
			res = (res + (x * y % mod)) % mod;
		}
		out.println(res);
	}

	class Combination2 {

		int n;
		long mod, fact[], ifact[];

		public Combination2(int n, long mod) {
			this.n = n;
			this.mod = mod;
			fact = new long[n];
			ifact = new long[n];
			fact[0] = 1;
			ifact[0] = 1;
			for (int i = 1; i < n; ++i) {
				fact[i] = fact[i - 1] * i % mod;
				ifact[i] = mod_pow(fact[i], mod - 2);
			}
		}

		long mod_pow(long x, long k) {
			long res = 1;
			while (k > 0) {
				if ((k & 1) == 1) res = res * x % mod;
				x = x * x % mod;
				k /= 2;
			}
			return res;
		}

		public long combination(int n, int k) {
			if (k < 0 || k > n) return 0;
			return fact[n] * ifact[k] % mod * ifact[n - k] % mod;
		}
	}

	public static void main(String[] args) throws Exception {
