	static long nCk(int n, int k) {
		if (n < k)
			return 0;
		else {
			return (fact[n] * inv(fact[n - k], MOD) % MOD * inv(fact[k], MOD) % MOD);
		}
	}

	static long inv(long a, long mod) {
		// if (gcd(a, mod) != 1)
		// throw new ArithmeticException("ax=1 mod mはgcd(a,x)!=1のとき解なし");
		a = a % mod;
		long b = mod;
		long p = 1, q = 0;
		// ? + qa = b
		// ? + pa = a (b>a)

		while (b > 1) {
			long c = b / a;
			b = b % a;
			q = q - p * c;
			long d = b;
			b = a;
			a = d;
			d = p;
			p = q;
			q = d;
		}
		while (q < 0)
			q += mod;
		return q;
	}

