	/// MAIN CODE
	public void run() throws IOException {
//		int TEST_CASE = Integer.parseInt(new String(io.nextLine()).trim());
		int TEST_CASE = 1;
		while(TEST_CASE-- != 0) {
			int h = io.nextInt();
			int w = io.nextInt();
			int hx = io.nextInt();
			int wx = io.nextInt();

			Combination comb = new Combination(2*100000+1000, mod);

			long ans = 0;
			for(int i = 0; i < h - hx; i++) {
				long x = comb.get(i + wx, wx);
				if (i > 0) x -= comb.get(i - 1 + wx, wx);
				x %= mod;
				ans += x * comb.get(w + h - 2 - (i + wx), w - 1 - wx) % mod;
			}
			io.out.println((ans % mod + mod) % mod);
		}
	}

	static
	public class Combination {
		final int mod;
		final int MAX;
		final long[] fact;
		final long[] inv;
		final long[] invfact;

		public Combination(int n, int mod) {
			this.mod = mod;
			MAX = n + 1;
			fact = new long[MAX];
			invfact = new long[MAX];
			inv = new long[MAX];

			inv[1] = 1;
			for(int i = 2; i < inv.length; i++) {
				inv[i] = inv[mod % i] * (mod - mod / i) % mod;
			}

			fact[0] = 1;
			invfact[0] = 1;
			for(int i = 1; i < inv.length; i++) {
				fact[i] = i * fact[i-1] % mod;
				invfact[i] = inv[i] * invfact[i-1] % mod;
			}
		}

		public long get(int n, int r) {
			return fact[n] * invfact[n - r] % mod * invfact[r] % mod;
		}

		public long getH(int n, int r) {
			return get(n + r - 1, r);
		}

		public long getFact(int n) {
			return fact[n];
		}
	}


