public class Main {
    static Scanner scanner = new Scanner(System.in);

    public static void main(String[]$) {
        int h = scanner.nextInt();
        int w = scanner.nextInt();
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        fac = new long[h + w + 1];
        inv = new long[h + w + 1];
        fac[0] = inv[0] = 1;
        for (int i = 1; i <= h + w; i++) {
            fac[i] = fac[i - 1] * i % 1000000007;
            inv[i] = powAndMod(fac[i], 1000000005);
        }

        long ans = 0;
        for (int i = b; i < w; i++) {
            ans = (ans + combination(i, h - a - 1) * combination(w - i - 1, a - 1) % 1000000007) % 1000000007;
        }
        System.out.println(ans);
    }

    static long[] fac, inv;
    static long combination(int h, int w) {
        return fac[h + w] * inv[h] % 1000000007 * inv[w] % 1000000007;
    }

    static long powAndMod(long a, long b) {
        if (b == 0)
            return 1;
        if ((b & 1) == 1)
            return a * powAndMod(a, b - 1) % 1000000007;
        return powAndMod(a * a % 1000000007, b / 2);
    }
}

import java.util.Scanner;

public class Main {

	static Scanner sc = new Scanner(System.in);
	static final int MOD = 1_000_000_007;

	public static void main(String[] args) {
		int H = sc.nextInt();
		int W = sc.nextInt();
		int A = sc.nextInt();
		int B = sc.nextInt();
		long[] row = new long[W];
		long before = comb(H - A - 1 + B, B);
		for (int i = B; i < W; ++i) {
			row[i] = before;
			before *= H - A + i;
			before %= MOD;
			before *= inv(i + 1);
			before %= MOD;
		}
		if (A == H - 1) {
			System.out.println(row[W - 1]);
			return;
		}
		long ans = 0;
		long after = 1;
		for (int i = W - 1; i >= B; --i) {
			ans += row[i] * after;
			ans %= MOD;
			after *= A - 1 + (W - i);
			after %= MOD;
			after *= inv(W - i);
			after %= MOD;
		}
		System.out.println(ans);
	}

	static long comb(long a, long b) {
		long ret = 1;
		for (int i = 0; i < b; ++i) {
			ret *= (a - i);
			ret %= MOD;
			ret *= inv(i + 1);
			ret %= MOD;
		}
		return ret;
	}

	static long inv(long v) {
		return pow(v, MOD - 2);
	}

	static long pow(long v, long p) {
		if (p == 0) return 1;
		if (p == 1) return v;
		long ret = pow(v, p / 2);
		ret *= ret;
		ret %= MOD;
		if (p % 2 == 1) {
			ret *= v;
			ret %= MOD;
		}
		return ret;
	}
}

