class Solver {
  final int h, w, a, b;
  final ModCalculator mc;
  final ModCombinationCache mcc;

  Solver(int h, int w, int a, int b) {
    this.h = h;
    this.w = w;
    this.a = a;
    this.b = b;
    this.mc = new ModCalculator(1_000_000_007L);
    this.mcc = new ModCombinationCache(this.mc);
  }

  // (1, 1)
  // (h, 1) -> (h - a, 1 + b)
  // (h, w)
  public long solve() {
    int i = h - a;
    int j = 1 + b;
    long answer = 0;
    while (i >= 1 && j <= w) {
//      System.err.printf("%d %d %d %d\n", i, j, i + j - 2, i - 1);
//      System.err.printf("%d %d %d %d\n", i, j, h + w - i - j, h - i);
      long v = mc.mul(mcc.getC(i + j - 2, i - 1), mcc.getC(h + w - i - j, h - i));
      answer = mc.add(answer, v);
//      System.err.printf("%d %d %d\n", i, j, answer);
      i--;
      j++;
    }
    return answer;
  }
}

