	using ti3 = Tuple<int, int, int>;
	using ti2 = Tuple<int, int>;
	internal class Program {
		private static void Main(string[] args) {
			var sw = new StreamWriter(OpenStandardOutput()) { AutoFlush = false };
			SetOut(sw);
			new Calc().Solve();
			Out.Flush();
		}

		public class Calc {
			public void Solve() {
				var factorial = new long[100001 * 2];
				var inverse = new long[100001 * 2];
				factorial[0] = inverse[0] = 1;
				for (var i = 1; i < factorial.Length; i++) {
					factorial[i] = MyMath.Mod(factorial[i - 1] * i);
					inverse[i] = MyMath.ModPow(factorial[i], MyMath.ModValue - 2);
				}

				Func<int, int, long> Combination = (n, k) =>
				{
					if (n - k < 0) return 0;
					var rt = factorial[n];
					rt *= inverse[k];
					rt %= MyMath.ModValue;
					rt *= inverse[n - k];
					return MyMath.Mod(rt);
				};

				int H = NextInt(), W = NextInt(), A = NextInt(), B = NextInt();
				var ans = MyMath.Mod(Combination(H + W-2, H-1));

				for (int i = 0; i < A; i++) {
					var a = H - i - 1;
					var b = B - 1;
					var ab = Combination(a + b, b);
					var goal = Combination(i + W - B - 1, i);
					ans = MyMath.Mod(ans - MyMath.Mod(ab * goal) + MyMath.ModValue);
				}
				MyMath.Mod(ans).WL();

				return;
			}
		}

	}
}
namespace Nakov.IO {
	using System;
	using System.Text;
	using System.Globalization;

	public static class Cin {
		public static string NextToken() {
			StringBuilder tokenChars = new StringBuilder();
			bool tokenFinished = false;
			bool skipWhiteSpaceMode = true;
			while (!tokenFinished) {
				int nextChar = Console.Read();
				if (nextChar == -1) {
					tokenFinished = true;
				} else {
					char ch = (char)nextChar;
					if (char.IsWhiteSpace(ch)) {
						if (!skipWhiteSpaceMode) {
							tokenFinished = true;
							if (ch == '\r' && (Environment.NewLine == "\r\n")) {
								Console.Read();
							}
						}
					} else {
						skipWhiteSpaceMode = false;
						tokenChars.Append(ch);
					}
				}
			}

			string token = tokenChars.ToString();
			return token;
		}

		public static int NextInt() {
			string token = Cin.NextToken();
			return int.Parse(token);
		}
		public static long NextLong() {
			string token = Cin.NextToken();
			return long.Parse(token);
		}
		public static double NextDouble(bool acceptAnyDecimalSeparator = true) {
			string token = Cin.NextToken();
			if (acceptAnyDecimalSeparator) {
				token = token.Replace(',', '.');
				double result = double.Parse(token, CultureInfo.InvariantCulture);
				return result;
			} else {
				double result = double.Parse(token);
				return result;
			}
		}
		public static decimal NextDecimal(bool acceptAnyDecimalSeparator = true) {
			string token = Cin.NextToken();
			if (acceptAnyDecimalSeparator) {
				token = token.Replace(',', '.');
				decimal result = decimal.Parse(token, CultureInfo.InvariantCulture);
				return result;
			} else {
				decimal result = decimal.Parse(token);
				return result;
			}
		}

	}
}

