namespace AtCoderConsole
{
    class Program
    {
        static void Main(string[] args)
        {
            // 標準入力から1行を取得
            string input = Console.ReadLine();

            // H W A Bを取得
            int h = int.Parse(input.Split(' ')[0]);
            int w = int.Parse(input.Split(' ')[1]);
            int a = int.Parse(input.Split(' ')[2]);
            int b = int.Parse(input.Split(' ')[3]);

            // 2次元配列を用意
            long[,] matrix = new long[h,w];

            // 初期化
            for(int i = 0; i < h; i++)
            {
                for(int j = 0; j < w; j++)
                {
                    if (i >= h - a && j < b)
                    {
                        matrix[i, j] = 0;
                    }
                    else if (i == 0 || j == 0)
                    {
                        matrix[i, j] = 1;
                    }
                    else
                    {
                        matrix[i, j] = -1;
                    }
                }
            }

            // 計算
            for(int i = 0; i < h; i++)
            {
                for(int j = 0; j < w; j++)
                {
                    if (matrix[i, j] == -1)
                    {
                        matrix[i, j] = matrix[i - 1, j] + matrix[i, j - 1];
                    }
                }
            }

            // 10^9+7で割った余りを求める
            long output = matrix[h - 1, w - 1] % 1000000007;

            // 標準出力に出力
            Console.WriteLine(output);
        }
    }
