			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size { get { return 1; } }
		public const long Mod = 1000000007;
		RandomSFMT rand = Program.rand;
		int H, W, A, B;
		void Read()
		{
			sc.Read(out H, out W, out A, out B);
		}
		long[] fact;
		void SolveOne()
		{
			var MAX = 300000;
			fact = new long[MAX];
			fact[0] = 1;
			for (var i = 1; i < MAX; i++) fact[i] = (i * fact[i - 1]) % Mod;
			var sum = 0L;
			//var c = (((fact[W + H - B - 2] * Func.Inverse(fact[W - B - 1], Mod)) % Mod) * Func.Inverse(fact[H - 1], Mod)) % Mod;
			for (var i = 0; i < H - A; i++)
			{
				sum = (sum + Binom(B - 1 + i, i) * Binom(W + H - B - 2 - i, W - B - 1) % Mod) % Mod;
				//sum = (sum + c) % Mod;
				//if (i == H - A - 1) break;
				//var x = ((B + i) * (long)(W + H - B - 1 - i)) % Mod;
				//var y = ((i + 1) * (long)(H - 2 - i)) % Mod;
				//c = (((c * x) % Mod) * Func.Inverse(y, Mod)) % Mod;
			}
			if (sum < 0) sum += Mod;
			pr.WriteLine(sum);
		}
		long Binom(int a, int b)
		{
			var x = fact[b] * fact[a - b] % Mod;
			return fact[a] * Func.Inverse(x, Mod) % Mod;
		}
	}
}
class Eq : IEqualityComparer<List<int>>
{
	public bool Equals(List<int> x, List<int> y)
	{
		if (x == null || y == null) return x == y;
		if (x.Count != y.Count) return false;
		for (var i = 0; i < x.Count; i++) if (x[i] != y[i]) return false;
		return true;
	}
	public int GetHashCode(List<int> obj)
	{
		var x = obj.Count.GetHashCode();
		foreach (var i in obj) x ^= i.GetHashCode();
		return x;
	}
}
