using System;
using System.Text;
using System.Collections.Generic;
class Solve{
    int H,W;
    int A,B;
    public Solve(){}
    StringBuilder sb;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        Read();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        Fact f = new Fact(H+W);
        long count = 0;
        for(int i=0;i<H-A;i++){
            count = (count + (f.GetConv(i+B-1,i) * f.GetConv(H-i+W-B-2,H-i-1) % Define.mod)) % Define.mod;
        }
        sb.Append(count+"\n");
    }
    void Read(){
        string[] str = Console.ReadLine().Split(' ');
        H = int.Parse(str[0]);
        W = int.Parse(str[1]);
        A = int.Parse(str[2]);
        B = int.Parse(str[3]);
    }    
}
class Fact{
    public long[] f;
    public long[] rf;
    public Fact(int N){
        f = new long[N+1];
        rf = new long[N+1];
        for(int i=0;i<N+1;i++){
            if(i == 0){
                f[i] = 1;
            }
            else{
                f[i] = (f[i-1]*i)%Define.mod;
            }
        }
        for(int i=N;i>=0;i--){
            if(i == N){
                rf[i] = pow(f[N],Define.mod-2);
            }
            else{
                rf[i] = rf[i+1]*(i+1)%Define.mod;
            }
        }
    }
    public long pow(long N,long K){
        if(K == 0){
            return 1;
        }
        else if(K % 2 == 0){
            long t = pow(N,K/2);
            return t*t%Define.mod;
        }
        else{
            return N*pow(N,K-1)%Define.mod;
        }
    }
    public long GetFact(int N){
        return f[N];
    }
    public long GetConv(int N,int R){
        return ((f[N]*rf[R])%Define.mod*rf[N-R])%Define.mod;
    }
}
public static class Define{
    public const long mod = 1000000007;
}

BEGIN{
	INT_WORD_SIZE=5;
	INT_BASE=10^INT_WORD_SIZE;
	INT_LENGTH=4;
}
function isneg(A){return +A[INT_LENGTH]}
function iszero(A,i)
{
	for(i=0;i<INT_LENGTH;++i)
	{
		if(A[i]!=0)return 0;
	}
	return 1;
}
function add(A,B_orig,B,i)
{
	copy(B_orig,B);
	for(i=0;i<=INT_LENGTH;++i)
	{
		A[i]+=B[i];
		if(A[i]>=INT_BASE){
			A[i]-=INT_BASE;
			A[i+1]+=1;
		}
	}
	A[INT_LENGTH]%=2;
}
function neg(A,i)
{
	for(i=0;i<INT_LENGTH;++i)
	{
		A[i]=INT_BASE-A[i]-(i!=0);
	}
	A[INT_LENGTH]=1-A[INT_LENGTH];
}
function cmp(A,B,i)#A<B?-1:A>B?1:0
{
	if(isneg(A))
	{
		if(isneg(B))
		{
			for(i=INT_LENGTH-1;i>=0;--i)
			{
				if(A[i]!=B[i])return A[i]<B[i]?1:-1;
			}
			return 0;
		}
		else return -1;
	}
	else
	{
		if(isneg(B))return 1;
		else
		{
			for(i=INT_LENGTH-1;i>=0;--i)
			{
				if(A[i]!=B[i])return A[i]<B[i]?-1:1;
			}
		}
	}
}
function mul(A,B_orig,B,negflag,i,j)
{
	copy(B_orig,B);
	if(isneg(A))
	{
		negflag+=1;
		neg(A);
	}
	if(isneg(B))
	{
		negflag+=1;
		neg(B);
	}
	for(i=INT_LENGTH-1;i>=0;--i)
	{
		for(j=INT_LENGTH-i-1;j>0;--j)
		{
			A[i+j]+=A[i]*B[j];
		}
		A[i]*=B[0];
	}
	for(i=0;i<INT_LENGTH-1;++i)
	{
		A[i+1]+=int(A[i]/INT_BASE);
		A[i]%=INT_BASE;
	}
	A[INT_LENGTH-1]%=INT_BASE;
	if(negflag==1)neg(A);
}
function div(A,B_orig,B,negflag,dividend,divisor,diff)#C-style
{
	copy(B_orig,B);
	if(isneg(A))
	{
		negflag+=1;
		neg(A);
	}
	if(isneg(B))
	{
		negflag+=1;
		neg(B);
	}
	copy(A,dividend);
	copy(B,divisor);
	input_num(sprintf("%.f",to_str(dividend)/to_str(divisor)),A);
	mul(divisor,A);
	neg(divisor);
	add(dividend,divisor);
	copy(B,divisor);
	diff=0;
	while(isneg(dividend))
	{
		diff-=1;
		add(dividend,divisor);
	}
	neg(divisor);
	while(cmp(dividend,B)!=-1)
	{
		diff+=1;
		add(dividend,divisor);
	}
	add_num(A,diff);
	if(negflag==1)neg(A);
}
function mod(A,B,tmp,modulo)
{
	copy(A,tmp);
	copy(B,modulo);
	if(isneg(modulo))neg(modulo);
	div(tmp,modulo);
	mul(tmp,modulo);
	neg(tmp);
	add(A,tmp);
	while(isneg(A))add(A,modulo);
}
function copy(A,B,i)
{
	for(i=0;i<=INT_LENGTH;++i)B[i]=A[i];
}
function input(x,A,i,negflag)
{
	if(x=="-0")x="0";
	negflag=sub(/^-/,"",x);
	x=sprintf("%"(INT_LENGTH*INT_WORD_SIZE)"s",x);
	for(i=0;i<INT_LENGTH;++i)
	{
		A[i]=+substr(x,(INT_LENGTH-i-1)*INT_WORD_SIZE+1,INT_WORD_SIZE);
	}
	A[INT_LENGTH]=0;
	if(negflag)neg(A);
}
function to_str(A_orig,A,negflag,flag,i,str)
{
	copy(A_orig,A);
	if(isneg(A))
	{
		negflag=1;
		neg(A);
	}
	for(i=INT_LENGTH-1;i>=0;--i)
	{
		if(flag)
		{
			str=str sprintf("%0" INT_WORD_SIZE "d",A[i]);
		}
		else if(A[i]>0)
		{
			str=sprintf("%d",A[i]);
			flag=1;
		}
	}
	if(!flag)str="0";
	return (negflag?"-":"")str;
}
