function add_num_impl(A,x,i)
{
	i=0;
	while(i<INT_LENGTH)
	{
		A[i]+=x%INT_BASE;
		x=int(x/INT_BASE);
		if(A[i]>=INT_BASE)
		{
			A[i]-=INT_BASE;
			A[i+1]+=1;
