def cumsum(lis, val=0, result=[]):
    if not lis:
        return result
    l, *others = lis
    return cumsum(
        others, val + l, result + [val + l]
    )


def row_update(row, depth, result=[]):
    if not depth:
        return result
    cumsum_row = cumsum(row)
    return row_update(
        cumsum_row, 
        depth - 1, 
        result + [row]
    )


