fn comb(n :usize,r :usize) -> usize {
    if n-r<r { return comb(n,n-r); }
    if r==0 { return 1; }
    if r==1 { return n; }

    let mut numer :Vec<usize> = vec![0;r];
    let mut denom :Vec<usize> = vec![0;r];
    for k in 0..r {
        numer[k]=n-r+k+1;
        denom[k]=k+1;
    }
    for p in 2..(r+1) {
        let pivot = denom[p-1];
        if pivot>1 {
            let offset = (n-r)%p;
            let mut k = p-1;
            loop {
                numer[k-offset] = numer[k-offset] / pivot;
                denom[k] = denom[k] / pivot;
                k = k+p;
                if k >= r { break; }
            }
        }
    }
    let mut result = 1;
    for k in 0..r {
        if numer[k] > 1 {
            result = (result * numer[k])%1000000007;
        }
    }
    result
}

