      for i in 1..n + 1 {
         fact[i] = fact[i - 1] * i as i64;
      }
      ifact[n] = fact[n as usize].inv();
      for i in (1..n + 1).rev() {
         ifact[i - 1] = ifact[i] * i as i64;
      }
      Comb {
         n: n,
         fact: fact,
         ifact: ifact,
      }
   }
   fn c(&self, n: usize, r: usize) -> Mint {
      if r > n || n > self.n {
         Mint::new(0)
      } else {
         self.fact[n] * self.ifact[r] * self.ifact[n - r]
      }
   }
}

